window.ROUTE_BAIYU = {"id":"baiyu","name":"白屿","floor":20,"flag1Week":53,"flag2Week":57,"flag1Need":60,"flag2Need":80,"flag1Label":"天台","flag2Label":"车站","tagline":"「他教你的第一件事，是把话说清楚。」","chapters":[{"id":"extra","title":"番外 · 他的三十岁","scenes":[{"no":1,"title":"三十岁那年的病房","week":0,"bg":"hospital_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"他三十岁那年，在住院部九楼躺了九天。"},{"t":"n","text":"病房三张床，他靠窗。窗帘是淡绿色的，他只拉一半。他说留一半能看见天色，方便判断几点。"},{"t":"n","text":"其实他枕边就有手机。他只是习惯用别的方式确认时间。"},{"t":"n","text":"入院那天是周一。他上午还在开会，中午吃了一个面包，下午开始胃疼，疼到背后出汗。"},{"t":"n","text":"同事把他送到医院。他坐在急诊的塑料椅上，还在用手机回消息，一个字一个字地打，打错了又删。"},{"t":"n","text":"医生问：「家属呢。」"},{"t":"n","text":"他说：「不用。」"},{"t":"n","text":"住院第二天，他让同事把笔记本电脑送了过来。"},{"t":"n","text":"他把它藏在床头柜下层，压在纸巾盒后面。护士来量体温，他就把被子往上拉一点。"},{"t":"n","text":"等人走了，他把电脑打开。屏幕的光在病房里显得很亮。"},{"t":"n","text":"他把方案里的一个日期从周一改到周三，又从周三改到周五。改完，他看了一遍，觉得可以了。"},{"t":"n","text":"隔壁床是个七十多岁的老先生，每天下午三点听评书。音量开得很小，像有人在被子里说话。"},{"t":"n","text":"老先生问他：「小伙子，你是做什么的。」"},{"t":"n","text":"他说：「做项目。」"},{"t":"n","text":"老先生说：「项目是什么。」"},{"t":"n","text":"他想了一会儿，说：「就是把一件本来做不完的事，做完。」"},{"t":"n","text":"老先生「哦」了一声，说：「那跟我年轻时候挑砖差不多。」"},{"t":"n","text":"他没接话。他觉得不太一样，但也懒得解释。"},{"t":"n","text":"他低头，在本子上写了一个字：缓。"},{"t":"n","text":"写完看了两秒，把那一页撕下来，贴在电脑屏幕边上。"},{"t":"n","text":"第二天早上，他把那张纸揭了。"},{"t":"n","text":"缓不了。项目排在那儿，一天一天往下压。"},{"t":"n","text":"晚上八点，沈迟打电话来。"},{"t":"npc","name":"沈迟","text":"想吃什么。"},{"t":"c","id":"baiyu","text":"随便。"},{"t":"npc","name":"沈迟","text":"你说随便，我就按我知道的买。"},{"t":"n","text":"他笑了一下，说：「那你就按你知道的买。」"},{"t":"n","text":"挂了电话，他把手机放在枕头下面。他怕自己一直看。"},{"t":"n","text":"他一天要看十七次表。左手腕那只深棕皮表带的腕表，是他三十岁生日自己买的。表盘很素，只有刻度。"},{"t":"n","text":"他不喜欢数字跳得太快的东西。"},{"t":"n","text":"第四天，沈迟来探视。她提着一个不锈钢保温桶，里面是小米粥。"},{"t":"n","text":"她穿一件深灰色的针织衫，头发扎在脑后，额前有几根碎发。她进门先看了一圈病房，然后才看他。"},{"t":"npc","name":"沈迟","text":"你瘦了。"},{"t":"c","id":"baiyu","text":"称过了。四斤。"},{"t":"npc","name":"沈迟","text":"你还称了。"},{"t":"c","id":"baiyu","text":"医院每天早上称。"},{"t":"n","text":"她没笑。她把保温桶放在床头柜上，伸手把他的电脑合上。"},{"t":"n","text":"他伸手想拦，手停在半空，又收回去。"},{"t":"npc","name":"沈迟","text":"你连生病都在算时间。"},{"t":"c","id":"baiyu","text":"不算，就来不及。"},{"t":"npc","name":"沈迟","text":"来不及什么。"},{"t":"n","text":"他没有答上来。"},{"t":"n","text":"她拧开保温桶，把粥倒进盖子里。热气升起来，把她的眼镜糊了一层。"},{"t":"n","text":"她摘下眼镜擦，动作很慢。"},{"t":"npc","name":"沈迟","text":"医生怎么说。"},{"t":"c","id":"baiyu","text":"说胃出了问题。说是饿出来的，也是急出来的。"},{"t":"npc","name":"沈迟","text":"急什么。"},{"t":"c","id":"baiyu","text":"项目下个月上线。"},{"t":"n","text":"她把盖子推到他手边。"},{"t":"npc","name":"沈迟","text":"粥凉了就不好喝了。"},{"t":"n","text":"他端起来喝了。粥有点烫，他没说。"},{"t":"n","text":"她坐在床边那张矮凳上，两个人都不说话。窗外有救护车的声音，由远及近，又由近及远。"},{"t":"n","text":"过了很久，她说：「我下个月要出差。去半个月。」"},{"t":"n","text":"他说：「去吧。」"},{"t":"n","text":"她看了他一会儿。他没抬头。"},{"t":"n","text":"她走的时候，把窗帘拉上了。"},{"t":"c","id":"baiyu","text":"别拉。"},{"t":"npc","name":"沈迟","text":"你该睡一会儿。"},{"t":"n","text":"门关上以后，他坐起来，把窗帘重新拉开。"},{"t":"n","text":"天已经黑了。楼下的停车场亮着一排黄色的灯，一辆车正在倒出来，倒得很慢。"},{"t":"n","text":"保温桶还开着。粥已经凉了，表面结了一层薄薄的膜。"},{"t":"n","text":"他把剩下的粥喝完了。凉的小米粥有点腥，他还是一口一口喝完了。"},{"t":"n","text":"他把保温桶盖好，放在床头柜上，想着下次带回去洗。"},{"t":"n","text":"后来他忘了。那个桶在床头柜上放了五天，直到出院那天，他才想起来。"}],"id":"baiyu_01"},{"no":2,"title":"出院那天","week":0,"bg":"hospital_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"出院是周四。"},{"t":"n","text":"他提前一天办了手续。护士说，明天上午就可以走。他说，能不能今天就办。"},{"t":"n","text":"护士看了他一眼，说：「你家属呢。」"},{"t":"n","text":"他说：「不用。」"},{"t":"n","text":"护士把单子推过来，指着最下面一行：「这里签字。」"},{"t":"n","text":"他签了名。白屿，两个字写得很快，最后一笔往上挑了一点。"},{"t":"n","text":"第二天上午十点，沈迟来了。她手里拿着他的外套，深灰色的，洗过，叠得很平。"},{"t":"n","text":"衬衫也带来了，白衬衫，领子熨过。"},{"t":"npc","name":"沈迟","text":"外面降温了。"},{"t":"n","text":"他接过外套，穿上。袖口有一道折痕，是她叠的时候压出来的。"},{"t":"n","text":"他把那道折痕捋了两下，没捋平。"},{"t":"n","text":"她替他把保温桶拎起来。"},{"t":"c","id":"baiyu","text":"这个我拿。"},{"t":"npc","name":"沈迟","text":"你拿着出院单。"},{"t":"n","text":"他就不争了。"},{"t":"n","text":"她开了车来。车里有一股很淡的柠檬味，是挂在后视镜下面的那块香片。"},{"t":"n","text":"广播在放一档老节目，主持人的声音很慢，在讲一个关于候鸟的故事。"},{"t":"n","text":"车开出医院大门，汇进主路。红灯。"},{"t":"n","text":"她把手放在方向盘上，没有看他。"},{"t":"npc","name":"沈迟","text":"我们谈谈。"},{"t":"c","id":"baiyu","text":"好。"},{"t":"npc","name":"沈迟","text":"等你忙完这一阵。"},{"t":"n","text":"他愣了一下。他其实没有说这句话，是她替他说了。"},{"t":"c","id":"baiyu","text":"等我忙完这一阵。"},{"t":"n","text":"她转过头看他。"},{"t":"npc","name":"沈迟","text":"哪一阵。"},{"t":"n","text":"绿灯亮了。后面的车按了一声喇叭。"},{"t":"n","text":"她把车往前开。"},{"t":"n","text":"他没有回答。"},{"t":"n","text":"他想说「这个项目上线之后」，但他知道上线之后还有下一个项目。他想说「等我把手上这些事交出去」，但他手上从来没有交完过。他想说「再给我半年」，这句话他在过去两年里说过四次。"},{"t":"n","text":"他低头看表。十点二十六分。"},{"t":"n","text":"这个动作他做了很多年，习惯到不需要经过脑子。等他抬起头，发现她在看他。"},{"t":"n","text":"她的眼神很平静，平静得让他有点慌。"},{"t":"n","text":"车停在他住的小区门口。她把手刹拉起来，没有熄火。"},{"t":"npc","name":"沈迟","text":"到了。"},{"t":"c","id":"baiyu","text":"上去坐一会儿。"},{"t":"npc","name":"沈迟","text":"不了。"},{"t":"n","text":"她把保温桶从后座拿过来，放在他腿上。"},{"t":"npc","name":"沈迟","text":"桶你先拿着。洗干净了再还我。"},{"t":"n","text":"他说：「好。」"},{"t":"n","text":"她看着他，好像还有话。他等她开口。"},{"t":"n","text":"她开口了。"},{"t":"npc","name":"沈迟","text":"白屿，你不是没有时间。"},{"t":"n","text":"她停了一下。"},{"t":"npc","name":"沈迟","text":"你是不想把时间给我。"},{"t":"n","text":"车里很安静。广播里那个主持人讲完了候鸟，开始放一段音乐。"},{"t":"n","text":"他想说不是。他想说，我只是想先把这件事做完，做完就有时间了，就有很多时间了。"},{"t":"n","text":"但他忽然发现，这句话他已经对自己说过很多次，每一次都信。"},{"t":"n","text":"他没有说出口。"},{"t":"n","text":"她替他按开了车门。"},{"t":"npc","name":"沈迟","text":"回去吧。粥别放太久。"},{"t":"n","text":"他拎着保温桶下车。风比他想的大。"},{"t":"n","text":"他站在路边，看着她倒车，掉头，汇进车流。"},{"t":"n","text":"他忽然想叫住她。他张了张嘴。"},{"t":"n","text":"她的车已经过了马路。"},{"t":"n","text":"那天下午，他睡了一觉。醒来的时候天黑了，屋子里没开灯。"},{"t":"n","text":"他把保温桶洗干净，倒扣在沥水架上。水一滴一滴往下掉。"},{"t":"n","text":"三个月后，他从一个老同事那里听说，沈迟调去了另一座城市。"},{"t":"n","text":"他打开手机，找到她的对话框。最后一条消息是她发的：「粥在冰箱第二层。」"},{"t":"n","text":"他打了一行字：「听说你走了。」"},{"t":"n","text":"看了很久，删掉。"},{"t":"n","text":"又打了一行：「到了那边，安顿好了告诉我。」"},{"t":"n","text":"又删掉。"},{"t":"n","text":"最后他什么也没发。"},{"t":"n","text":"再后来，他听说她结婚了。对方是她在新城市认识的人。他没有去。"},{"t":"n","text":"两年后搬家，他收拾厨房，从柜子最里面翻出那个保温桶。"},{"t":"n","text":"桶底有一圈水锈，洗不掉了。"},{"t":"n","text":"他拿在手里站了一会儿，然后放进了垃圾袋。"},{"t":"n","text":"那天他在新家的阳台上坐到很晚。楼下有人在遛狗，绳子拖在地上，声音很轻。"},{"t":"n","text":"他想，如果他当时答上来了，会怎么样。"},{"t":"n","text":"他想不出来。"},{"t":"n","text":"从那以后，他做什么都留三分。方案留三分余地，话留三分不说，人留三分不靠近。"},{"t":"n","text":"留三分不是不认真。留三分是，万一哪一天要收回来，不至于收不干净。"}],"id":"baiyu_02"},{"no":3,"title":"两年后，一份合约","week":0,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"三十二岁那年，他一共接两个项目。"},{"t":"n","text":"不是接不到更多。是他算过，一个项目从进场到结项，平均五个月。两个项目错开来做，一个进场，一个收尾，正好一年。再多，就要开始糊弄。"},{"t":"n","text":"他不糊弄。"},{"t":"n","text":"那天下午，他去签一份顾问合约。会议室是借的，桌上还留着上一场会的矿泉水瓶。"},{"t":"n","text":"对接人是个三十出头的年轻人，姓周，衬衫袖口卷着，讲话很快。"},{"t":"n","text":"周把合约推过来，说：「白老师，条款您看看，有问题随时提。」"},{"t":"n","text":"他把合约从头到尾看了一遍。看到第七条，停下来。"},{"t":"c","id":"baiyu","text":"我的权限边界在哪里。"},{"t":"n","text":"周愣了一下。"},{"t":"npc","name":"周","text":"您随意。您是这个项目里最懂的人。"},{"t":"c","id":"baiyu","text":"不行。"},{"t":"n","text":"他把合约转过去，指着第七条。"},{"t":"c","id":"baiyu","text":"我要知道我能定什么，不能定什么。不然出了事，谁都说不清。"},{"t":"n","text":"周笑了一下，说：「白老师，您太谨慎了。」"},{"t":"c","id":"baiyu","text":"谨慎不花钱。不谨慎才花钱。"},{"t":"n","text":"他从西装内袋里拿出一支笔。黑色的，很普通，笔帽上有一道很浅的划痕。"},{"t":"n","text":"那是他三十岁生日，沈迟送的。她说，你总丢笔，买支好点的。"},{"t":"n","text":"他在合约空白处加了一行字，写得一笔一划："},{"t":"n","text":"「顾问不参与甲方人事、绩效与晋升评定；不对甲方员工进行单独考核。」"},{"t":"n","text":"这行字不是临时想的。"},{"t":"n","text":"他的笔记本第一页，抄着同样的一句话，抄了三年。下面还有三行："},{"t":"n","text":"「一，不进编制。二，不做直属上级。三，项目结束即离场。」"},{"t":"n","text":"这三行，是他从上一家公司出来那天写的。"},{"t":"n","text":"那天他清完工位，抱着一个纸箱站在电梯口，忽然发现自己不知道下一步去哪。"},{"t":"n","text":"他在楼下坐了两个小时，喝完一瓶水，然后回家，打开电脑，做了第一版顾问合约。"},{"t":"n","text":"写完，他把笔推回去，说：「加上这条，我签。」"},{"t":"n","text":"周看了那行字，看了很久。"},{"t":"npc","name":"周","text":"白老师，您这是……"},{"t":"c","id":"baiyu","text":"这是保护你们，也是保护我。"},{"t":"n","text":"周没再问。他叫来行政，重新打印了一份。"},{"t":"n","text":"他签字的时候，笔尖在纸上顿了一下。白屿，两个字。"},{"t":"n","text":"签完，他把笔帽扣上，\"咔\"的一声。"},{"t":"n","text":"走出大楼，天在下雨。"},{"t":"n","text":"他没带伞。他站在门口的屋檐下，看着雨斜着落下来，把台阶打湿。"},{"t":"n","text":"有人跑过去，把包顶在头上。有人站在他旁边，打电话叫车。"},{"t":"n","text":"他没有叫车。他站着等。"},{"t":"n","text":"雨小了以后，他走进雨里。西装肩头很快就湿了一片，颜色变深。"},{"t":"n","text":"他不跑。"},{"t":"n","text":"路过一家便利店，他进去买了一把伞。"},{"t":"n","text":"出来的时候，雨已经停了。"},{"t":"n","text":"他把伞收起来，拿在手里，一直拿到公司楼下。"},{"t":"n","text":"手机在口袋里震了一下。是学校就业中心发来的消息：下周有一场校园招聘会，想请他去终面，只面最后一轮。"},{"t":"n","text":"他站在路口回了一条："},{"t":"n","text":"「可以。我只问三个问题。」"},{"t":"n","text":"对方回得很快：「哪三个？」"},{"t":"n","text":"他没有回。"},{"t":"n","text":"他心里有三个问题，用了很多年：你负责哪一部分；如果这件事做不成，你会怎么做；你想从这里得到什么。"},{"t":"n","text":"三个问题问完，他大概就知道这个人能不能一起做事。"},{"t":"n","text":"他不看简历上的学校，也不看绩点。他看人说话的时候，眼睛落在哪里。"},{"t":"n","text":"这一年，他的行李箱一直没有完全拆开。洗漱包在箱子侧袋里，随时可以拉上拉链。"},{"t":"n","text":"他不在任何一间公司里有一张固定的桌子。"},{"t":"n","text":"他在门口站着，把话说完，然后走。"},{"t":"n","text":"他的手机里有一个备忘录，标题是「明年」。"},{"t":"n","text":"里面只有一行：南边，旧粮仓，小剧场。"},{"t":"n","text":"那条记录是三年前写的。三年里他改了七次日期，一次也没去过。"},{"t":"n","text":"今年他打算去。"}],"id":"baiyu_03"}]},{"id":"ch1","title":"第一章 · 合作开始","scenes":[{"no":4,"title":"三个问题","week":43,"bg":"gym_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"招聘会在体育馆。两百个展位，每个展位后面坐着一个人，表情差不多。"},{"t":"n","text":"空调开得很足，但人太多，空气还是闷的。地上贴着黄色的引导线，被人踩得起了边。"},{"t":"n","text":"你手里有八份简历，打印店老板说纸张是加厚的，摸起来确实比普通纸硬一点。"},{"t":"n","text":"你排了四十分钟，前面还有五个人。"},{"t":"n","text":"轮到你的时候，你把简历递过去。对方扫了一眼，问：「你组织过一场活动？说说看，你负责哪一部分。」"},{"t":"n","text":"你说了三分钟。从场地谈到预算，从预算谈到物料，从物料谈到当天来了多少人。"},{"t":"n","text":"他打断你。"},{"t":"c","id":"baiyu","text":"我问的是，你负责哪一部分。"},{"t":"n","text":"你停住了。"},{"t":"n","text":"体育馆很吵，隔壁展位有人在笑。你听见自己的心跳。"},{"t":"n","text":"你重新说了一遍。这次只说了一分钟。"},{"t":"n","text":"你说，场地是你去谈的，谈到第三家才肯给折扣。物料清单是你列的，你加了两样别人没想到的东西。当天来的人比你预估的多三十个，你在门口站了两个小时，一直在调整动线。"},{"t":"n","text":"他点点头，在简历上画了个圈，把纸推回来。"},{"t":"c","id":"baiyu","text":"下午三点，楼下咖啡馆。迟到就不用来了。"},{"t":"n","text":"他起身去接水。西装外套搭在椅背上，袖口露出一截白衬衫，熨得很平。"},{"t":"n","text":"你低头看简历。他画的圈在「负责」两个字上。"},{"t":"n","text":"后来你才知道，他叫白屿，三十二岁，是几家公司共用的外部顾问。这个行业里说话算数的人不多，他算一个。"},{"t":"n","text":"他不属于任何一个展位。学校请他来做终面，他只在最后一轮出现，只问三个问题。"},{"t":"n","text":"两点五十，你到了咖啡馆。"},{"t":"n","text":"他已经在了，靠窗的位置，面前两杯水。一杯是他的，一杯是给你的。"},{"t":"n","text":"杯子外壁有水珠，说明倒了一会儿了——他提前到了，并且替你也倒了一杯。"},{"t":"n","text":"你坐下。他没有寒暄，把你的简历摊在桌上，用手指按住一角。"},{"t":"c","id":"baiyu","text":"第一个问题。刚才那个活动，如果预算砍掉一半，你会砍掉什么。"},{"t":"n","text":"你说了。他说：「还有吗。」"},{"t":"n","text":"你又说了一个。他点头，在纸上记了一笔。"},{"t":"c","id":"baiyu","text":"第二个问题。这件事如果最后没做成，你会怎么办。"},{"t":"n","text":"这个问题问得很轻，但你没有立刻答上来。"},{"t":"n","text":"他看着你，没有催。"},{"t":"n","text":"你说，你会先把没做成的部分弄清楚，是判断错了，还是执行没到位；然后再决定要不要重来。"},{"t":"n","text":"他说：「如果重来一次，还是不成呢。」"},{"t":"n","text":"你说，那就不重来了。但你要知道为什么。"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"baiyu","text":"第三个问题。"},{"t":"n","text":"他喝了一口水。"},{"t":"c","id":"baiyu","text":"你想从这里得到什么。"},{"t":"n","text":"这个问题他在很多人身上问过。"},{"t":"n","text":"有的人答「成长」，有的人答「钱」，有的人答「一个机会」。答完之后，他会再问一句「然后呢」。"},{"t":"n","text":"大部分人在「然后呢」这里卡住。"},{"t":"n","text":"他把杯子放回桌上，等着。他没有催你。"},{"t":"n","text":"窗外的公交站有人上车，有人下车。玻璃上有一层薄薄的灰。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"一个更大的平台","hint":"去更大的地方 · 稳定","eff":{"fin":6.0,"stress":8.0,"aff":5.0},"reply":[{"t":"n","text":"你说，你想去一个更大的地方。你想看看一件事在足够多的资源下，能做到什么程度。"},{"t":"n","text":"他看了你一会儿。"},{"t":"c","id":"baiyu","text":"大平台会教你流程。也会让你变成流程的一部分。"},{"t":"n","text":"你说你知道。"},{"t":"c","id":"baiyu","text":"知道和准备好，是两件事。"},{"t":"n","text":"他在纸上写了两个字，把纸推过来给你看：「耐性」。"},{"t":"n","text":"「大平台最缺这个。你进去以后，前两年可能都在做同一件小事。你能忍，就成。」"}]},{"label":"B","text":"一个能把事做成的机会","hint":"赌一个可能 · 成长快","eff":{"cre":6.0,"fin":3.0,"stress":6.0,"aff":4.0},"reply":[{"t":"n","text":"你说，你想去一个能让自己把事做完的地方。哪怕地方小一点，人少一点。"},{"t":"n","text":"他问：「做完了以后呢。」"},{"t":"n","text":"你说，再做下一件。"},{"t":"n","text":"他笑了一下，很轻。"},{"t":"c","id":"baiyu","text":"这个答案，我一年能听到十次。做到的人，一年一个。"},{"t":"n","text":"他在纸上写：「买单」。"},{"t":"c","id":"baiyu","text":"记住这两个字。你的想法值多少钱，不取决于它多好，取决于谁愿意为它付钱。"}]},{"label":"C","text":"一份安稳","hint":"稳一点 · 家里放心","eff":{"familyRel":5.0,"happy":4.0,"stress":-2.0,"aff":3.0},"reply":[{"t":"n","text":"你说，你想要一份安稳的工作。你说得很坦白，没有绕。"},{"t":"n","text":"他点头，没有露出那种「年轻人不该这样想」的表情。"},{"t":"c","id":"baiyu","text":"安稳不是错。错的是想要安稳，又嫌它不刺激。"},{"t":"n","text":"他在纸上写：「边界」。"},{"t":"c","id":"baiyu","text":"体制里最要紧的是把边界弄清楚。谁的活，谁签字。你弄清楚了，就能待很久。"}]},{"label":"D","text":"自己给自己打工","hint":"自己定价 · 自由有代价","eff":{"cre":8.0,"fin":-2.0,"happy":5.0,"stress":2.0,"aff":4.0},"reply":[{"t":"n","text":"你说，你不想进任何一家公司。你想自己接活。"},{"t":"n","text":"他挑眉，第一次露出一点意外的样子。"},{"t":"c","id":"baiyu","text":"你知道自己接活，第一年大概挣多少吗。"},{"t":"n","text":"你说了一个数。他摇头。"},{"t":"c","id":"baiyu","text":"比这个还少。而且没人给你交社保。"},{"t":"n","text":"他在纸上写：「报价」。"},{"t":"c","id":"baiyu","text":"第一条规矩：报价的时候，别把自己算便宜了。你算便宜了，客户不会感激你，只会觉得你就值这个价。"}]}]},{"t":"n","text":"三个问题问完，他把简历折了一下，放进西装内袋。"},{"t":"n","text":"不是扔掉。是收起来。"},{"t":"n","text":"他从口袋里拿出一张名片，放在桌上，推过来。名片很素，只有名字、电话、邮箱，没有公司。"},{"t":"c","id":"baiyu","text":"周三之前，把你想做的事写成一页纸，发我。"},{"t":"n","text":"你说：「我还没入职。」"},{"t":"c","id":"baiyu","text":"所以才要写。"},{"t":"n","text":"他站起来，把椅子推回原位。"},{"t":"c","id":"baiyu","text":"入职以后，你写的东西就要给很多人看了。现在没人看，正好练。"},{"t":"n","text":"他走了。玻璃门开了一下，外面的热空气涌进来。"},{"t":"n","text":"你坐在原位，把那杯水喝完。水已经不凉了。"},{"t":"n","text":"名片背面有一行很小的字，是手写的：「先看，别急着证明自己。」"},{"t":"n","text":"你把名片翻过来又翻过去，看了两遍。"},{"t":"n","text":"走出咖啡馆，你在门口站了一会儿。"},{"t":"n","text":"玻璃门里，他还坐在原位，把那张纸翻过来，写了几个字。"},{"t":"n","text":"你没有看清写的是什么。"},{"t":"n","text":"很多年后你才知道，他每面一个人，都会写下对方的名字，后面跟一个问号。"},{"t":"n","text":"问号划掉，才算过关。"}],"id":"baiyu_04"},{"no":5,"title":"周三之前","week":45,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"工位在靠窗第三排。显示器比你的脸还大，键盘上有一层薄灰。"},{"t":"n","text":"入职第三天，你才知道工位是上一个离职的人留下的。抽屉里还有半包纸巾和一枚回形针。"},{"t":"n","text":"群里有九十九加的消息，你一条都不敢漏。你把重要的话复制到自己的备忘录，标上日期。"},{"t":"n","text":"周一下午两点，白屿来了。"},{"t":"n","text":"他不是你们的员工。他刷卡进不来，每次都要前台打电话确认。"},{"t":"n","text":"他一周来两次，一次两小时，都在小会议室。会议结束他就走，从不在工位区停留。"},{"t":"n","text":"他把一个文件夹放在你桌上。"},{"t":"c","id":"baiyu","text":"这个，周三之前给我。"},{"t":"n","text":"说完他就进了会议室。"},{"t":"n","text":"你打开文件夹。里面只有三页纸，没有说明，没有格式要求，没有「参考案例」。"},{"t":"n","text":"第一页是一张平面图，标了七个位置。第二页是预算表，只填了一半。第三页是空白的。"},{"t":"n","text":"你翻来覆去看了三遍，确定自己没有漏掉什么附件。"},{"t":"n","text":"你抬头，会议室的门关着，磨砂玻璃后面有两个人影。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问清楚再动手","hint":"先问一句 · 少走弯路","eff":{"eq":3.0,"int":3.0,"stress":2.0,"aff":5.0},"reply":[{"t":"n","text":"你敲了会议室的门。"},{"t":"n","text":"他正在跟组长说话，看见你，抬手示意你进来。"},{"t":"n","text":"你问了三个问题：这七个位置是要选一个，还是都要做；预算表是按季度还是按项目；第三页要写结论还是写过程。"},{"t":"n","text":"他一条一条答完。答得很短，但每一条都答了。"},{"t":"c","id":"baiyu","text":"还有吗。"},{"t":"n","text":"你说没有了。"},{"t":"n","text":"他点点头。"},{"t":"c","id":"baiyu","text":"以后都这样。别猜。"},{"t":"n","text":"你出门的时候，听见他对组长说：「这个可以。」"},{"t":"n","text":"组长说：「新人，还在看。」"},{"t":"c","id":"baiyu","text":"看的是会不会问。"}]},{"label":"B","text":"自己猜着做","hint":"先做出来 · 压力 ↑","eff":{"int":4.0,"stress":6.0,"happy":-2.0,"aff":1.0},"reply":[{"t":"n","text":"你没有问。你觉得问太多会显得不专业。"},{"t":"n","text":"你花了三个晚上，把七个位置全做了一遍，预算按季度拆，第三页写了两千字。"},{"t":"n","text":"周三上午，你把文件发过去。"},{"t":"n","text":"下午他来了，翻了两页，合上。"},{"t":"c","id":"baiyu","text":"方向错了。重做。"},{"t":"n","text":"你愣在那儿。"},{"t":"n","text":"他把文件夹推回来，指着平面图：「这七个位置，有三个是承重墙，动不了。你做了三个不能做的。」"},{"t":"n","text":"你脸发烫。"},{"t":"n","text":"他没有生气。他只是把话说完了，然后补了一句：「下次先问。」"},{"t":"n","text":"他没生气，你反而更难受。"}]},{"label":"C","text":"准点下班","hint":"守住自己的时间 · 心情 ↑","eff":{"happy":4.0,"stress":-3.0,"aff":2.0},"reply":[{"t":"n","text":"六点整，你关了电脑。"},{"t":"n","text":"办公室里没人抬头，但你知道有人看见了。"},{"t":"n","text":"你在电梯口碰到白屿。他也在等电梯，手里拿着外套。"},{"t":"n","text":"电梯来了，你们一起进去。楼层数字一格一格往下跳。"},{"t":"c","id":"baiyu","text":"东西做完了？"},{"t":"n","text":"你说，明天做。"},{"t":"n","text":"他「嗯」了一声。"},{"t":"n","text":"到一楼，门开了。"},{"t":"c","id":"baiyu","text":"明天九点，别迟到。"},{"t":"n","text":"他说完就走了。你站在原地，觉得这句话不算批评，但也不像鼓励。"}]}]},{"t":"n","text":"那周你交上去的东西，他只批注了四行。"},{"t":"n","text":"第一行：「第 2 条，数据来源写上。」"},{"t":"n","text":"第二行：「第 4 条，不要用『大概』。」"},{"t":"n","text":"第三行：「第 6 条，你自己信吗。」"},{"t":"n","text":"第四行：「第 7 条，重写。」"},{"t":"n","text":"第四行后面画了一个很小的箭头，指向页边。"},{"t":"n","text":"页边空白处，还有一行更小的字：「写完再来找我，不要发邮件。」"},{"t":"n","text":"你在工位上坐了很久，把第 7 条重写了三遍。"},{"t":"n","text":"晚上八点，你去会议室找他。他已经收拾好包，看见你，把包又放下了。"},{"t":"n","text":"他坐下，接过你的纸，看了两分钟。"},{"t":"c","id":"baiyu","text":"这版可以。"},{"t":"n","text":"就三个字。你走出会议室的时候，脚步比进去时轻。"},{"t":"n","text":"走廊尽头，你听见组长在跟别人说话。"},{"t":"n","text":"「白老师算我们的人吗。」"},{"t":"n","text":"「不算。他是外面的。合同到期就走。」"},{"t":"n","text":"你停在原地，等他们说完才继续走。"}],"id":"baiyu_05"},{"no":6,"title":"末班车","week":46,"bg":"office_night_desk","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"十一点，办公室还剩四个人。"},{"t":"n","text":"你关电脑的时候，白屿正好从会议室出来。他看了看表，又看了看你。"},{"t":"c","id":"baiyu","text":"走吗。"},{"t":"n","text":"你说走。"},{"t":"n","text":"你们一起等电梯。电梯里有镜子，你看见自己眼下有一圈青色。"},{"t":"n","text":"他站在你左边，外套搭在手臂上，领带松了一格。"},{"t":"n","text":"出了大堂，风很大。写字楼门口的旗子被吹得啪啪响。"},{"t":"c","id":"baiyu","text":"你坐地铁？"},{"t":"n","text":"你说坐。"},{"t":"c","id":"baiyu","text":"顺路。"},{"t":"n","text":"你们往地铁口走。路上没什么人，便利店的灯很亮，里面坐着一个打瞌睡的店员。"},{"t":"n","text":"地铁口有一个卖关东煮的摊子，白色的汤在锅里翻，冒着热气。"},{"t":"n","text":"他停了一下，问你：「吃吗。」"},{"t":"n","text":"你说不太饿。"},{"t":"n","text":"他还是买了两串，一串萝卜，一串豆腐，递给你一串。"},{"t":"c","id":"baiyu","text":"吃点热的。胃会舒服。"},{"t":"n","text":"你接过来。萝卜很烫，你换了两只手。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问他为什么不做全职","hint":"问身份 · 不越界","eff":{"aff":5.0,"eq":2.0,"int":1.0},"reply":[{"t":"n","text":"你问他，为什么不做全职。以他的资历，去哪家公司都能有个位置。"},{"t":"n","text":"他把豆腐吃掉，用纸擦手。"},{"t":"c","id":"baiyu","text":"全职就得站队。"},{"t":"n","text":"他说，他以前在一家公司待过六年。做到负责人的位置，一天开五个会，其中四个会跟做事没关系。"},{"t":"c","id":"baiyu","text":"后来我发现，我在那家公司最重要的作用，是让别人觉得这件事有人管。"},{"t":"n","text":"他说，他不喜欢那个作用。"},{"t":"c","id":"baiyu","text":"现在这样挺好。一年接两个项目，做完就走。谁也不用防着我，我也不用防着谁。"},{"t":"n","text":"你说：「那不是很没有归属感。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"baiyu","text":"是有一点。"},{"t":"n","text":"他把竹签丢进垃圾桶。"},{"t":"c","id":"baiyu","text":"但归属感这个东西，我给不起。所以我也不拿。"}]},{"label":"B","text":"说自己的事","hint":"说真话 · 关系近","eff":{"aff":4.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你说，你其实每天下班都在想白天哪句话说错了。"},{"t":"n","text":"你说，你怕自己做得不好，怕别人看出来你什么都不懂。"},{"t":"n","text":"他没有说「你已经很好了」。他也没有说「大家都是这么过来的」。"},{"t":"n","text":"他把萝卜吃完，才开口。"},{"t":"c","id":"baiyu","text":"我刚工作那两年，每天回家都要把当天的话在脑子里过一遍。"},{"t":"n","text":"他说，有一年他连续三个月失眠。后来他发现，他怕的不是做错，是「被发现做错」。"},{"t":"c","id":"baiyu","text":"这两种怕不一样。前一种能改，后一种改不了，只能熬。"},{"t":"n","text":"你问他熬过来了吗。"},{"t":"c","id":"baiyu","text":"熬过来了。但也留下了点东西。"},{"t":"n","text":"你问什么东西。"},{"t":"n","text":"他笑了笑，没说。"}]},{"label":"C","text":"沉默走完这段路","hint":"不说 · 保持距离","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"你没有问。你专心吃那串萝卜。"},{"t":"n","text":"他也不说话。两个人并排走，脚步声在夜里很清楚。"},{"t":"n","text":"走到地铁口，他把竹签丢进垃圾桶，等你先下去。"},{"t":"n","text":"楼梯很长，灯是感应的，走一段亮一段。"},{"t":"n","text":"下到一半，他忽然说："},{"t":"c","id":"baiyu","text":"你话不多。"},{"t":"n","text":"你说，不知道说什么。"},{"t":"c","id":"baiyu","text":"不知道说什么的时候，不说也行。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"总比说些没用的好。"}]}]},{"t":"n","text":"地铁站台上人很少。电子屏显示末班车还有四分钟。"},{"t":"n","text":"他站在黄线后面，两只手插在口袋里。"},{"t":"n","text":"车来了。他让你先上。"},{"t":"n","text":"车厢里空着一半座位。你们隔着一个人的距离坐下。"},{"t":"n","text":"他靠着椅背，闭上眼睛。你偷偷看了他一眼。"},{"t":"n","text":"他的眼下有阴影，比你的深。左眉尾有一道很浅的竖纹，是常年皱眉留下的。"},{"t":"n","text":"到站，他睁开眼，站起来。"},{"t":"c","id":"baiyu","text":"到了。"},{"t":"n","text":"你跟着下车。他说他还要换乘。"},{"t":"n","text":"他抬手看表的动作，在地铁口的灯下很清楚。"},{"t":"n","text":"表盘上有一道很浅的划痕，横在十二点下面。"},{"t":"n","text":"你问他这块表戴了多久。"},{"t":"c","id":"baiyu","text":"四年。"},{"t":"n","text":"你说四年不算久。"},{"t":"n","text":"他说：「四年里我换过三个城市。」"},{"t":"n","text":"说完他就不说了。"},{"t":"n","text":"走出闸机，他往另一个方向走。走了几步，回头。"},{"t":"c","id":"baiyu","text":"明天九点。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他转过身，走进换乘通道。通道里的灯很白，他的影子被拉得很长。"}],"id":"baiyu_06"},{"no":7,"title":"背锅","week":47,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"数据错了。"},{"t":"n","text":"会议室的大屏上，那张表第三列整整高了一倍。客户方的周姐把笔放下，问：「这个数是谁做的。」"},{"t":"n","text":"所有人的目光都落在你身上。"},{"t":"n","text":"你的手心开始出汗。你把手放在桌子下面，在裤子上擦了一下。"},{"t":"n","text":"白屿坐在长桌的另一头。他没有替你说话。"},{"t":"n","text":"他看着你，像在等你自己开口。"},{"t":"n","text":"会议室很安静。空调的出风口在头顶响，声音像有人在很远的地方吹气。"},{"t":"n","text":"你脑子里飞快地过：这张表是别人给你的原始数据，你按原表算的。但你也确实没有核。"},{"t":"n","text":"周姐又问了一遍：「谁做的。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"认下，并给出补救方案","hint":"先把事接住 · 让人放心","eff":{"eq":5.0,"stress":8.0,"aff":5.0},"reply":[{"t":"n","text":"你说：「是我。」"},{"t":"n","text":"会议室里的空气动了一下。"},{"t":"n","text":"你接着说：「今晚我会把口径重新跑一遍，明早九点前发出来。第三列的问题出在单位换算，其他列我今晚一起核。」"},{"t":"n","text":"周姐看了你两秒，说：「明早九点。」"},{"t":"n","text":"你说：「九点。」"},{"t":"n","text":"会议继续。你的耳朵一直在烧。"},{"t":"n","text":"散会后，白屿在茶水间等你。"},{"t":"n","text":"他倒了两杯水，递给你一杯。"},{"t":"c","id":"baiyu","text":"你想清楚要说什么了吗。"},{"t":"n","text":"你说想清楚了。"},{"t":"n","text":"他点头。"},{"t":"c","id":"baiyu","text":"下次，先把数字对三遍。第一遍对自己，第二遍对原始数据，第三遍对常识。"},{"t":"n","text":"他喝了一口水，补了一句："},{"t":"c","id":"baiyu","text":"今天这个，不算坏事。你今晚会学到的东西，比这个项目里其他所有事加起来都多。"}]},{"label":"B","text":"说明真相","hint":"把话说清楚 · 不背不该背的","eff":{"int":3.0,"eq":3.0,"stress":4.0,"aff":3.0},"reply":[{"t":"n","text":"你说，数据是别人给的，你按原表算的。"},{"t":"n","text":"你说完，把手机拿出来，找到那条聊天记录，投到屏幕上。"},{"t":"n","text":"截图里的时间是上周四晚上十一点四十分。对方发来表格，说「按这个做」。"},{"t":"n","text":"会议室更安静了。"},{"t":"n","text":"周姐看完，转头看向另一边。那边的人开始解释，说是「临时调整过一版，忘了同步」。"},{"t":"n","text":"白屿看完，只说了一句："},{"t":"c","id":"baiyu","text":"知道了。下次收到表，先核一遍。"},{"t":"n","text":"散会后，他叫住你。"},{"t":"c","id":"baiyu","text":"今天你没错。"},{"t":"n","text":"你说谢谢。"},{"t":"c","id":"baiyu","text":"但我还是要说你一句。"},{"t":"n","text":"你站着没动。"},{"t":"c","id":"baiyu","text":"你刚才投屏的时候，手在抖。你把话说清楚了，但你是带着气说的。"},{"t":"n","text":"他说，把话说清楚，和把气撒出来，是两件事。"},{"t":"c","id":"baiyu","text":"前一件让你站得住。后一件让你站不稳。"}]},{"label":"C","text":"沉默","hint":"不说是非 · 但会被记住","eff":{"stress":6.0,"happy":-4.0,"aff":0.0},"reply":[{"t":"n","text":"你什么也没说。"},{"t":"n","text":"周姐等了几秒，说：「那先按错的这个版本往下走，回头再对。」"},{"t":"n","text":"会开完了。事情也算过去了。"},{"t":"n","text":"你回到工位，坐了很久。屏幕上是那张表，第三列的数字亮得刺眼。"},{"t":"n","text":"你想解释。你想说不是你的错。你想说你也只是按要求做的。"},{"t":"n","text":"但你没有说。"},{"t":"n","text":"下午，你听见组长在走廊里跟别人说：「以后重要的表，先过一遍老陈那边。」"},{"t":"n","text":"老陈是组里的老人。你不认识他，但你知道这句安排意味着什么。"},{"t":"n","text":"白屿走之前，路过你的工位。他停了半秒，什么也没说。"}]}]},{"t":"n","text":"白屿离开前，又回了一次茶水间。"},{"t":"n","text":"他把杯子洗干净，倒扣在沥水架上。"},{"t":"n","text":"经过你工位的时候，他停下来。"},{"t":"c","id":"baiyu","text":"职场里最贵的不是能力。"},{"t":"n","text":"他把外套穿上，理了理袖口。"},{"t":"c","id":"baiyu","text":"是让人放心。"},{"t":"n","text":"他走了。"},{"t":"n","text":"你把这句话写在便签上，贴在显示器边。"},{"t":"n","text":"便签是黄色的。贴上去以后，你每次抬头都能看见。"},{"t":"n","text":"当天晚上，你收到一封邮件。白屿发给组长，抄送你。"},{"t":"n","text":"邮件只有五行，写清了三件事：原始数据由谁提供，换算口径由谁确认，最终审核由谁签字。"},{"t":"n","text":"最后一行是：「以上为项目流程记录，供后续追溯。」"},{"t":"n","text":"他没有替你开脱，也没有替你定罪。他只是把这件事的边界画了出来。"},{"t":"n","text":"你把这封邮件单独建了一个文件夹，名字叫「流程」。"},{"t":"n","text":"很多年以后你才明白，那封邮件是他能给你的最大的东西——不是保护，是方法。"}],"id":"baiyu_07"}]},{"id":"ch2","title":"第二章 · 分寸与靠近","scenes":[{"no":8,"title":"两个人的加班","week":49,"bg":"office_night_desk","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"项目进入中期，评审定在下周三。"},{"t":"n","text":"客户方临时改了功能需求，原来做好的三块内容要拆掉重做。组长在群里发了一句「辛苦大家」，然后就没有然后了。"},{"t":"n","text":"晚上十点，办公室里只剩两个人。"},{"t":"n","text":"一个是你。另一个是白屿。"},{"t":"n","text":"他把会议室的灯调暗了一档，投影关掉，只留桌上的台灯。"},{"t":"n","text":"然后他去接了两杯热水，从公文包里拿出两个茶包。"},{"t":"c","id":"baiyu","text":"只有这个。将就喝。"},{"t":"n","text":"你把茶包放进杯子。水是刚烧的，茶叶浮在上面，慢慢地沉下去。"},{"t":"n","text":"你们并排坐着，中间隔了两个座位。"},{"t":"n","text":"门是开着的。走廊的感应灯灭了，只剩会议室这一块亮。"},{"t":"n","text":"你写你的部分，他改他的部分。键盘声、翻纸声、笔尖划过纸面的声音。"},{"t":"n","text":"中间他起身两次。一次去接水，一次站在窗边看了一会儿。"},{"t":"n","text":"十一点四十，你终于忍不住问了一句。"},{"t":"n","text":"你说：「门要不要关一下，有点冷。」"},{"t":"n","text":"他没有立刻回答。他起身，走过去，把门掩到只剩一条缝。"},{"t":"n","text":"然后他回来，把自己的西装外套从椅背上拿起来，递给你。"},{"t":"c","id":"baiyu","text":"披着。"},{"t":"n","text":"你说不用。"},{"t":"c","id":"baiyu","text":"披着。别逞强。"},{"t":"n","text":"你披上了。西装里有很淡的洗衣液味道，还有一点纸张和墨水的味道。"},{"t":"n","text":"他坐下，把椅子往外挪了半尺。"},{"t":"n","text":"改到十二点，他忽然停下来。"},{"t":"c","id":"baiyu","text":"这一句，删掉。"},{"t":"n","text":"你问为什么。"},{"t":"c","id":"baiyu","text":"你在解释。评审不看解释，看结论。"},{"t":"n","text":"你把那一句删了。删掉以后，整段顺了很多。"},{"t":"n","text":"你说：「你怎么一眼就看出来。」"},{"t":"c","id":"baiyu","text":"因为我以前也这么写。写了很多年。"},{"t":"n","text":"他端起杯子，茶已经凉了。他还是喝了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问他家里的事","hint":"问一句 · 关系会近","eff":{"aff":5.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你问他，这么晚回去，家里人不会等吗。"},{"t":"n","text":"他敲键盘的手停了一下。"},{"t":"c","id":"baiyu","text":"我一个人住。"},{"t":"n","text":"他说得很平，像在说天气。"},{"t":"n","text":"你没有接话。沉默了几秒，他自己往下说了。"},{"t":"c","id":"baiyu","text":"房子是租的。两室，一间放东西，基本不用。"},{"t":"n","text":"你问：「那为什么要租两室。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"baiyu","text":"可能是不想让人觉得，我只有一个房间那么大。"},{"t":"n","text":"他说完，自己笑了一下，好像觉得这句话有点矫情。"},{"t":"c","id":"baiyu","text":"当我没说。"},{"t":"n","text":"你把茶喝完，把杯子放回桌上。"},{"t":"n","text":"那一刻你忽然意识到，他不是没有生活。他是把生活压缩到了一个可以随时拉上拉链的尺寸。"}]},{"label":"B","text":"说谢谢","hint":"道一句谢 · 不越界","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"你说，谢谢他留下来。"},{"t":"n","text":"他抬眼看你。"},{"t":"c","id":"baiyu","text":"这是我的项目。"},{"t":"n","text":"你说：「你其实可以明天再看。」"},{"t":"n","text":"他沉默了一下。"},{"t":"c","id":"baiyu","text":"明天有明天的事。"},{"t":"n","text":"他把一页纸翻过去。"},{"t":"c","id":"baiyu","text":"而且，我不太喜欢把事留到明天。"},{"t":"n","text":"你说：「这是好习惯还是坏习惯。」"},{"t":"n","text":"他没有抬头。"},{"t":"c","id":"baiyu","text":"看跟谁比。"},{"t":"n","text":"你笑了一下。他也笑了一下，很轻，只有嘴角动。"}]},{"label":"C","text":"把话题拉回方案","hint":"只谈工作 · 安全","eff":{"aff":4.0,"int":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你把屏幕转过去，问他第三页的逻辑对不对。"},{"t":"n","text":"他凑过来看。很近，你能看见他鬓角的白发，比你以为的多。"},{"t":"n","text":"他指着第二段说：「这里，你写的是过程。评审要看的是判断。」"},{"t":"n","text":"你说：「判断我还没想好。」"},{"t":"c","id":"baiyu","text":"那就把没想好的地方写出来。"},{"t":"n","text":"你说这样会不会显得不专业。"},{"t":"c","id":"baiyu","text":"不专业的是装作想好了。"},{"t":"n","text":"他把屏幕推回来。"},{"t":"c","id":"baiyu","text":"评审的人不傻。你留一个空，他一眼就看见。你写清楚为什么留空，他反而会问你。"}]}]},{"t":"n","text":"凌晨一点半，方案改完了。"},{"t":"n","text":"他把最后一页打印出来，用订书机订上，放在文件夹里。"},{"t":"n","text":"你的手机响了，是叫车软件。"},{"t":"n","text":"他也拿出手机，叫了一辆。"},{"t":"c","id":"baiyu","text":"你住哪边。"},{"t":"n","text":"你说了地址。"},{"t":"n","text":"他低头看了一眼手机，说：「顺路。一起。」"},{"t":"n","text":"你知道不顺路。你没有拆穿。"},{"t":"n","text":"楼下风很大。他把外套从你肩上拿回去，穿上，扣子只扣了一颗。"},{"t":"n","text":"车来了。他拉开后门，让你先上。"},{"t":"n","text":"你坐进去，他跟着坐进来，坐在另一边。"},{"t":"n","text":"报地址的时候，他先报了你的。"},{"t":"n","text":"车开出去，路灯一段一段从车窗上掠过。"},{"t":"n","text":"快到的时候，他忽然开口。"},{"t":"c","id":"baiyu","text":"车牌我记了。"},{"t":"n","text":"你愣了一下。他说：「习惯了。一个人在外面，晚上坐车，把车牌发给一个信得过的人。」"},{"t":"n","text":"你问：「那你发给谁。」"},{"t":"n","text":"他看着窗外。"},{"t":"c","id":"baiyu","text":"我不发。"},{"t":"n","text":"车停在小区门口。你下车，弯腰对车里说谢谢。"},{"t":"n","text":"他抬起手，示意你进去。"},{"t":"n","text":"你走到门口，回头看了一眼。车还停在那里，没有走。"},{"t":"n","text":"直到你进了单元门，那辆车的尾灯才慢慢移开。"}],"id":"baiyu_08"},{"no":9,"title":"一张过期的体检单","week":50,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"公司的年度体检报告发下来了。"},{"t":"n","text":"你的那份装在牛皮纸信封里，封口用胶水粘着。你拆的时候撕歪了。"},{"t":"n","text":"报告上有一页是彩色的图表，几项指标带着向上的箭头。"},{"t":"n","text":"你不懂那些缩写，但你懂箭头。"},{"t":"n","text":"下午三点，你在茶水间冲咖啡。白屿进来接水。"},{"t":"n","text":"他看见你手里的报告，问：「有问题？」"},{"t":"n","text":"你说，有几项偏高，医生建议复查。"},{"t":"n","text":"他点头，没有说「年轻人要注意身体」这种话。"},{"t":"c","id":"baiyu","text":"去复查。"},{"t":"n","text":"你说：「应该没事。」"},{"t":"c","id":"baiyu","text":"应该没事，和确定没事，是两件事。"},{"t":"n","text":"他把水杯放下，看着你。"},{"t":"c","id":"baiyu","text":"复查一次两百块，半天时间。你现在不去，将来要花的是二十倍。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他走了以后，你把报告折起来，塞进包里。"},{"t":"n","text":"那天傍晚，你去他常用的会议室送文件。"},{"t":"n","text":"他不在。桌上摊着一叠纸，最上面那张是体检单。"},{"t":"n","text":"不是今年的。日期是去年十一月。"},{"t":"n","text":"信封没有拆。"},{"t":"n","text":"你站在桌边，手里拿着要送的文件，站了大概十秒。"},{"t":"n","text":"走廊里有脚步声。你退出来，把文件放在门口的架子上。"},{"t":"n","text":"第二天上午，他来了。你把文件递给他，顺口问了一句。"},{"t":"n","text":"你说：「你的体检做了吗。」"},{"t":"n","text":"他抬起头，看了你一眼。"},{"t":"c","id":"baiyu","text":"怎么问这个。"},{"t":"n","text":"你说，昨天看见了。"},{"t":"n","text":"他没有生气，也没有解释。他把文件翻到签字页，签了名。"},{"t":"c","id":"baiyu","text":"等项目结束。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"提醒他去","hint":"提一句 · 他会记住","eff":{"aff":5.0,"happy":1.0,"stress":-1.0},"reply":[{"t":"n","text":"你说：「你上次也是这么说的。」"},{"t":"n","text":"这句话说出口，你自己也愣了一下。你没有资格这样跟他说话。"},{"t":"n","text":"他的手停在半空。"},{"t":"n","text":"会议室里很静。窗外有人在楼下打电话，声音很轻，听不清说什么。"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"baiyu","text":"上次是什么时候。"},{"t":"n","text":"你说：「报销单上的日期，去年十一月。我上个月整理档案看见的。」"},{"t":"n","text":"他没有说话。"},{"t":"n","text":"过了很久，他说："},{"t":"c","id":"baiyu","text":"你记性很好。"},{"t":"n","text":"你说：「不是我记性好。是那张单子一直没拆。」"},{"t":"n","text":"他笑了一下。那个笑很淡，也不像高兴。"},{"t":"c","id":"baiyu","text":"行。我记着。"}]},{"label":"B","text":"陪他去","hint":"陪一趟 · 越过一步","eff":{"aff":6.0,"happy":2.0,"fin":-2.0},"reply":[{"t":"n","text":"你说：「这周六上午，我陪你去。」"},{"t":"n","text":"他挑眉。"},{"t":"c","id":"baiyu","text":"你陪我去。"},{"t":"n","text":"你说：「你不去，我也不去复查。」"},{"t":"n","text":"他看了你很久。你能感觉到他在判断这句话的分量，也在判断自己该退到哪一步。"},{"t":"n","text":"最后他说：「周六上午九点。别迟到。」"},{"t":"n","text":"周六，你们在医院门诊楼碰面。他穿得很随便，深色卫衣，外面一件夹克。"},{"t":"n","text":"你第一次看见他不穿西装。他的肩膀比你想的窄一点，人也显得没那么高。"},{"t":"n","text":"排队的时候，他站在你后面，一直没说话。"},{"t":"n","text":"抽血的时候，护士说：「握拳。」"},{"t":"n","text":"他握着拳，手背上青色的血管很清楚。"},{"t":"n","text":"出来的时候，你把两瓶水递给他一瓶。"},{"t":"c","id":"baiyu","text":"谢谢。"},{"t":"n","text":"他说这两个字的样子很认真，认真得有点生疏。"}]},{"label":"C","text":"不提","hint":"不越界 · 保持距离","eff":{"aff":2.0,"stress":1.0},"reply":[{"t":"n","text":"你没有再说。"},{"t":"n","text":"这是他的事。你只是项目组里的一个人。"},{"t":"n","text":"他签完字，把文件合上，递还给你。"},{"t":"c","id":"baiyu","text":"这个流程，下次让行政先过一遍再给我。"},{"t":"n","text":"你说好，拿着文件出门。"},{"t":"n","text":"走到门口，你回头看了一眼。他坐在那里，正在看手机。屏幕的光照在他脸上。"}]}]},{"t":"n","text":"那天下班，你在电梯里又碰到他。"},{"t":"n","text":"电梯里只有你们两个。楼层数字一格一格往下跳。"},{"t":"n","text":"他忽然说：「复查，你去吗。」"},{"t":"n","text":"你说去。"},{"t":"n","text":"他点头。"},{"t":"c","id":"baiyu","text":"那就好。"},{"t":"n","text":"电梯到一楼。门开了，他先出去，站在门边等你。"},{"t":"n","text":"走到大厅，他停下。"},{"t":"c","id":"baiyu","text":"你刚才那句话，我回去想了一下。"},{"t":"n","text":"你问他哪句。"},{"t":"c","id":"baiyu","text":"『上次也是这么说的』。"},{"t":"n","text":"他看着你。"},{"t":"c","id":"baiyu","text":"我确实经常这么说。说的时候是真心的，说完就忘了，也是真的。"},{"t":"n","text":"他说完，自己摇摇头。"},{"t":"c","id":"baiyu","text":"这个毛病不好。"},{"t":"n","text":"你说：「那就改。」"},{"t":"n","text":"他看了你一眼，笑了一下。"},{"t":"c","id":"baiyu","text":"你说得倒轻巧。"},{"t":"n","text":"他推开玻璃门，走出去。风把他的衣角吹起来一点。"}],"id":"baiyu_09"},{"no":10,"title":"一顿饭","week":51,"bg":"izakaya_night","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"阶段验收过了。组长说要聚餐，订了一家火锅店。"},{"t":"n","text":"白屿没去。他说他不参加甲方的聚餐，这是合约里写的。"},{"t":"n","text":"晚上八点，你从火锅店出来，胃里很胀。街上人不多，风里有葱花的味道。"},{"t":"n","text":"你走了两条街，看见一家小馆子。门脸很窄，招牌上写着「老街面馆」，灯管有一根不亮。"},{"t":"n","text":"白屿坐在里面靠墙的那张桌子边。"},{"t":"n","text":"他也看见你了。"},{"t":"n","text":"他抬手，示意你进来。"},{"t":"n","text":"你推门进去。门上的铃铛响了一声。"},{"t":"c","id":"baiyu","text":"没吃饱？"},{"t":"n","text":"你说吃饱了。"},{"t":"c","id":"baiyu","text":"那坐一会儿。"},{"t":"n","text":"你在他对面坐下。"},{"t":"n","text":"他面前是一碗面，吃了大半。旁边有一碟腌萝卜，几乎没动。"},{"t":"n","text":"桌子是老式的折叠桌，桌角用胶带缠过。"},{"t":"c","id":"baiyu","text":"这家店开了二十多年。我刚工作的时候就在这儿吃。"},{"t":"n","text":"老板从柜台后面探出头，看了他一眼。"},{"t":"npc","name":"老板","text":"好久没来了。"},{"t":"c","id":"baiyu","text":"搬得远了。"},{"t":"npc","name":"老板","text":"还是老样子？"},{"t":"c","id":"baiyu","text":"老样子。"},{"t":"n","text":"老板看了你一眼，没多问，转身去下面。"},{"t":"n","text":"你说：「他认识你。」"},{"t":"c","id":"baiyu","text":"认识十几年了。他记得我不吃葱。"},{"t":"n","text":"你问他那时候在哪工作。"},{"t":"n","text":"他说了一个名字。是一家很大的公司。"},{"t":"n","text":"你说：「那不是很好。」"},{"t":"c","id":"baiyu","text":"那时候觉得很好。后来觉得不好。再后来觉得，也就那样。"},{"t":"n","text":"他把筷子放下。"},{"t":"c","id":"baiyu","text":"你今年多大。"},{"t":"n","text":"你说了。"},{"t":"n","text":"他点头。"},{"t":"c","id":"baiyu","text":"我三十二。"},{"t":"n","text":"他说这句话的时候，语气很平，像在报一个数字。"},{"t":"n","text":"但你知道他不是在报数字。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我知道」","hint":"不回避 · 接住","eff":{"aff":6.0,"happy":3.0,"eq":2.0},"reply":[{"t":"n","text":"你说：「我知道。」"},{"t":"n","text":"他抬眼看你。"},{"t":"c","id":"baiyu","text":"你知道什么。"},{"t":"n","text":"你说：「知道你三十二。知道你一年接两个项目。知道你项目做完就走。」"},{"t":"n","text":"你没有说「知道你不打算留下」。"},{"t":"n","text":"但这句话在你们之间，就是那个意思。"},{"t":"n","text":"他沉默了很久。"},{"t":"n","text":"老板在柜台后面按遥控器，电视换了一个台，声音调得很小。"},{"t":"c","id":"baiyu","text":"既然知道，那就别猜。"},{"t":"n","text":"你说：「我没猜。我在问。」"},{"t":"n","text":"他愣了一下，然后笑了。"},{"t":"c","id":"baiyu","text":"行。你问。"},{"t":"n","text":"你问他，三十二岁是什么感觉。"},{"t":"n","text":"他想了想。"},{"t":"c","id":"baiyu","text":"是发现自己能做的事，比想做的事少。"},{"t":"n","text":"他拿起筷子，又放下。"},{"t":"c","id":"baiyu","text":"三十岁之前，我觉得时间是用不完的。过了三十，忽然就算得清了。"}]},{"label":"B","text":"说自己的怕","hint":"说真话 · 压力 ↓","eff":{"aff":5.0,"happy":3.0,"stress":-3.0},"reply":[{"t":"n","text":"你说，你现在很怕。"},{"t":"n","text":"你说，你怕自己干不了几年就被淘汰，怕每个月看工资条的时候那种感觉，怕过年回家亲戚问「现在做什么」。"},{"t":"n","text":"你说，你更怕的是，你其实不知道自己想做什么。"},{"t":"n","text":"你没有哭。你只是说话的速度快了一点。"},{"t":"n","text":"他没有打断你。等你说完，他把那碟腌萝卜往你那边推了推。"},{"t":"c","id":"baiyu","text":"吃点这个。面汤咸。"},{"t":"n","text":"你夹了一块。很酸，你皱了下眉。"},{"t":"n","text":"他才开口。"},{"t":"c","id":"baiyu","text":"你说的这些怕，我都有过。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"现在也有。只是换了个样子。"},{"t":"n","text":"你问他换成什么样了。"},{"t":"c","id":"baiyu","text":"以前怕做不成。现在怕做成了，发现不是自己想要的。"}]},{"label":"C","text":"岔开话题","hint":"不深入 · 保持分寸","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"你问他这面好不好吃。"},{"t":"n","text":"他看了你一眼，然后说：「汤不错。面一般。」"},{"t":"n","text":"你说那你也吃了大半碗。"},{"t":"c","id":"baiyu","text":"因为我不挑。"},{"t":"n","text":"你笑。他也笑。"},{"t":"n","text":"你们都松了一口气。"},{"t":"n","text":"话题转到了别的地方。他说这条街以前有一个卖糖水的摊子，夏天排队排到路口。"},{"t":"n","text":"你说你没见过。"},{"t":"c","id":"baiyu","text":"你当然没见过。那时候你还在上小学。"},{"t":"n","text":"他说完自己也停了一下。"},{"t":"n","text":"有些话一出口，年龄就自己站出来了。躲都躲不掉。"},{"t":"n","text":"他把碗里剩下的汤喝完，放下。"},{"t":"n","text":"「我像你这么大的时候，觉得三十岁是很远的事。」"}]}]},{"t":"n","text":"他从口袋里拿出钱包，去柜台结账。"},{"t":"n","text":"你要付自己那碗，他摆手。"},{"t":"c","id":"baiyu","text":"下次你请。"},{"t":"n","text":"你说好。"},{"t":"n","text":"走出馆子，街上的风比刚才凉。他把夹克拉链拉到一半。"},{"t":"n","text":"你们往地铁站的方向走。走了大概两百米，他忽然停下。"},{"t":"c","id":"baiyu","text":"有件事，我可以说一半。"},{"t":"n","text":"你看着他。"},{"t":"c","id":"baiyu","text":"我三十岁那年，住过一次院。"},{"t":"n","text":"他说得很慢。"},{"t":"c","id":"baiyu","text":"住的时间不长。但那次之后，有些事就不一样了。"},{"t":"n","text":"你问哪件事。"},{"t":"n","text":"他摇头。"},{"t":"c","id":"baiyu","text":"还没到说的时候。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他好像有点意外你会这么答。"},{"t":"n","text":"他看了你一会儿，说：「你不问为什么。」"},{"t":"n","text":"你说：「你说还没到说的时候。」"},{"t":"n","text":"他低下头，笑了一下，声音很轻。"},{"t":"c","id":"baiyu","text":"嗯。"},{"t":"n","text":"到了路口，他停下来。"},{"t":"c","id":"baiyu","text":"明天九点。"},{"t":"n","text":"你说周末不上班。"},{"t":"c","id":"baiyu","text":"那周一九点。"},{"t":"n","text":"他转身往反方向走。"},{"t":"n","text":"你走了十几步，回头。"},{"t":"n","text":"他还站在路灯下，低头看手机。屏幕的光把他的下颌线照得很清楚。"},{"t":"n","text":"他没有抬头。"}],"id":"baiyu_10"},{"no":11,"title":"评审会","week":52,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"评审会九点开始，来了十一个人。"},{"t":"n","text":"客户方的负责人坐在主位。周姐在旁边，翻开文件夹。"},{"t":"n","text":"你们组的方案三十五页，打印了十二份，装订用的是蓝色的夹条。"},{"t":"n","text":"白屿坐在长桌的另一头。按规矩，他不坐主位，也不坐你旁边。"},{"t":"n","text":"前四十分钟很顺利。翻到第二十三页，负责人停住了。"},{"t":"n","text":"他说，这个公共阅览区能不能砍掉。八百平方米，不产生租金，还要配两个人。"},{"t":"n","text":"他说：「预算超了。这一块最不划算。」"},{"t":"n","text":"会议室里安静了一下。"},{"t":"n","text":"这个阅览区是白屿坚持要留的。他在第一次方案会上说，一个对公众开放的空间，必须有一块不用消费就能坐下来的地方。"},{"t":"n","text":"你看着他。他在翻自己的本子。"},{"t":"n","text":"负责人问：「白老师，您的意见。」"},{"t":"n","text":"他把本子合上。"},{"t":"c","id":"baiyu","text":"不建议削减。"},{"t":"n","text":"他只说了六个字。"},{"t":"n","text":"负责人笑了一下，说：「白老师，情怀归情怀，账要算。」"},{"t":"c","id":"baiyu","text":"算过了。砍掉这八百平方米，能省百分之六的预算。但招商那边少了一个能拿来说事的公共配套，租金谈不上去。三年后回头算，是亏的。"},{"t":"n","text":"他说完，把一张纸推过去。上面是他自己做的测算。"},{"t":"n","text":"负责人看了两分钟，没说话。"},{"t":"n","text":"会议室的空气有点僵。"},{"t":"n","text":"这时候，坐在周姐旁边的一个人开口了。他说得很随意，像开玩笑。"},{"t":"n","text":"他说：「白老师对项目组这位同事，是真上心啊。方案都替人算好了。」"},{"t":"n","text":"空气彻底僵住。"},{"t":"n","text":"你的耳朵一下热了。你想解释，又不知道该解释什么。"},{"t":"n","text":"白屿没有立刻回答。他把笔放下，坐直。"},{"t":"c","id":"baiyu","text":"我和项目组的同事是合作关系。"},{"t":"n","text":"他的声音不大，但会议室里每个人都听见了。"},{"t":"c","id":"baiyu","text":"我的意见只对项目负责。刚才那份测算，数据来自客户的招商报告，不是我一个人的判断。需要的话，我可以把推导过程发给在座各位。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"如果有人认为我的意见有别的动机，可以现在提出，我退出这个项目的评审。"},{"t":"n","text":"没有人说话。"},{"t":"n","text":"负责人咳了一声，说：「白老师严重了。那就按您的测算，再看一版。」"},{"t":"n","text":"会议继续。"},{"t":"n","text":"接下来的一个小时，你没有说一句话。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我知道了」","hint":"把委屈咽下 · 懂事","eff":{"aff":4.0,"happy":-3.0,"eq":3.0},"reply":[{"t":"n","text":"散会后，你在走廊里叫住他。"},{"t":"n","text":"你说：「我知道了。以后在会上，我不替你说话。」"},{"t":"n","text":"他停下脚步。"},{"t":"c","id":"baiyu","text":"你没有替我说话。"},{"t":"n","text":"你说：「我看了你一眼。」"},{"t":"n","text":"他沉默了一下。"},{"t":"c","id":"baiyu","text":"那也不行。"},{"t":"n","text":"他的语气比平时硬。"},{"t":"c","id":"baiyu","text":"在这里，你多看谁一眼，都会被人记住。你还没到可以被记住的时候。"},{"t":"n","text":"你说：「那你呢。」"},{"t":"c","id":"baiyu","text":"我无所谓。我做完这个项目就走。"},{"t":"n","text":"这句话说得很快。说完，他自己也停住了。"},{"t":"n","text":"走廊尽头的窗户开着，风把百叶窗吹得响了一下。"}]},{"label":"B","text":"反驳「你不也替我说话」","hint":"把话说开 · 会吵","eff":{"aff":3.0,"happy":-2.0,"stress":4.0,"eq":2.0},"reply":[{"t":"n","text":"你说：「那你刚才不是也在替我说话。」"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"baiyu","text":"我在替方案说话。"},{"t":"n","text":"你说：「有区别吗。」"},{"t":"n","text":"他看了你几秒。"},{"t":"c","id":"baiyu","text":"有。"},{"t":"n","text":"他把手里的文件夹换到另一只手。"},{"t":"c","id":"baiyu","text":"方案是项目的东西。你是你自己。这两样混在一起，最后两样都保不住。"},{"t":"n","text":"你说：「所以你觉得我会拖累你。」"},{"t":"n","text":"他闭了一下眼睛。"},{"t":"c","id":"baiyu","text":"我没这么说。"},{"t":"n","text":"你说：「你就是这个意思。」"},{"t":"n","text":"他没有再解释。"},{"t":"c","id":"baiyu","text":"你要这么想，我也没办法。"},{"t":"n","text":"他走了。你站在原地，手心是凉的。"},{"t":"n","text":"那是你们认识以来，第一次把话说到这个地步。"}]},{"label":"C","text":"沉默","hint":"不辩解 · 心里记账","eff":{"aff":2.0,"happy":-4.0,"stress":3.0},"reply":[{"t":"n","text":"你什么也没说。"},{"t":"n","text":"你回到工位，把评审记录一个字一个字敲进电脑。"},{"t":"n","text":"敲到「合作关系」四个字的时候，你的手指停了一下。"},{"t":"n","text":"下午，白屿从你工位旁边走过去。他走得很慢。"},{"t":"n","text":"他没有停。"},{"t":"n","text":"你把那四个字删掉，重打了一遍。"}]}]},{"t":"n","text":"散会后，周姐在门口等你。"},{"t":"n","text":"她压低声音：「刚才那句话，你别往心里去。他就是嘴快。」"},{"t":"n","text":"你说没事。"},{"t":"n","text":"她看了你一眼。"},{"t":"npc","name":"周姐","text":"白老师这个人，做事很清楚。清楚的人，也容易被说闲话。"},{"t":"n","text":"她说完就走了。"},{"t":"n","text":"当天下午，会议纪要发出来了。"},{"t":"n","text":"在「公共阅览区」这一条下面，写着："},{"t":"n","text":"「顾问意见：不建议削减。理由见附件测算。意见人：白屿。」"},{"t":"n","text":"他署了自己的名。"},{"t":"n","text":"不是「项目组」，不是「顾问团队」。是他自己的名字。"},{"t":"n","text":"你看着那行字，看了很久。"},{"t":"n","text":"你知道这意味着什么。如果三年后这个决定被证明是错的，被翻出来的就是这三个字。"},{"t":"n","text":"快下班的时候，他来到你工位旁边。"},{"t":"n","text":"他把一份打印好的附件放在你桌上。"},{"t":"c","id":"baiyu","text":"这个你留着。"},{"t":"n","text":"你打开。是他那份测算，最后附了一张纸，写着推导过程，字很小，很密。"},{"t":"n","text":"在纸的最下面，有一行字："},{"t":"n","text":"「在会上，我不可能站在你这边。这是我唯一能站的地方。」"},{"t":"n","text":"你把纸对折，放进抽屉。"},{"t":"n","text":"他还没走。他站在那里，好像在等你说点什么。"},{"t":"n","text":"你抬头。他的表情很平静，但眼睛下面有很深的阴影。"},{"t":"c","id":"baiyu","text":"今天的话，我说得重了。"},{"t":"n","text":"你说：「没有。你说得对。」"},{"t":"n","text":"他看了你一会儿，点点头。"},{"t":"n","text":"他转身走了。你听见他的皮鞋声在走廊里一下一下地远去。"},{"t":"n","text":"那天晚上，你把那张纸看了三遍。"},{"t":"n","text":"你想起他说「我无所谓，我做完这个项目就走」。"},{"t":"n","text":"你第一次意识到，他所谓的「无所谓」，是因为他从来没有打算留下来。"}],"id":"baiyu_11"},{"no":12,"title":"医院的天台","week":53,"bg":"rooftop_sunset","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"你从急诊出来，手里捏着一张缴费单。"},{"t":"n","text":"医生说的话你记住了一半：先观察，明天复查，这几天不要熬夜。"},{"t":"n","text":"「不要熬夜」这四个字，你今年听过很多次。"},{"t":"n","text":"手机在口袋里震了一下。是白屿。"},{"t":"n","text":"他只发了四个字：「上楼。天台。」"},{"t":"n","text":"天台在住院部九楼。门是消防门，推开有一声闷响。"},{"t":"n","text":"上面晾着几条床单，白的，被风吹得鼓起来，像有人藏在里面。"},{"t":"n","text":"他站在栏杆边。"},{"t":"n","text":"西装外套搭在手臂上，衬衫袖子卷到小臂。手里拿着一罐咖啡，已经喝完了，还捏在手里。"},{"t":"n","text":"他听见门响，转过身来。"},{"t":"n","text":"他没有问你怎么样。"},{"t":"n","text":"他先把外套抖开，递过来。"},{"t":"c","id":"baiyu","text":"披着。别逞强。"},{"t":"n","text":"你说不用，你不冷。"},{"t":"n","text":"他没有收回手。"},{"t":"c","id":"baiyu","text":"我知道你不冷。披着。"},{"t":"n","text":"你披上了。"},{"t":"n","text":"西装很大，肩线落在你手臂外面。袖口长得盖住手背。"},{"t":"n","text":"里面有很淡的洗衣液味道，和他办公室里的一样。还有一点咖啡的味道。"},{"t":"n","text":"他转回去，靠着栏杆，看着楼下。"},{"t":"n","text":"楼下是急诊的入口，红色的灯一直亮着。救护车进去一辆，又出来一辆。"},{"t":"n","text":"你站到他旁边，隔着一个人的距离。"},{"t":"n","text":"风把缴费单吹得哗哗响。你把它折起来，塞进口袋。"},{"t":"n","text":"沉默了很久。久到你以为他把你叫上来，只是为了让你吹吹风。"},{"t":"n","text":"他开口了。"},{"t":"c","id":"baiyu","text":"我三十岁那年，也住过一次院。"},{"t":"n","text":"他说得很平，像在讲一个别人的项目。"},{"t":"n","text":"你转头看他。他没有看你，视线落在楼下。"},{"t":"c","id":"baiyu","text":"九楼。靠窗那张床。窗帘是淡绿色的，我只拉一半。"},{"t":"n","text":"他说，住院第二天，他让同事把电脑送了过来，藏在床头柜下层。"},{"t":"n","text":"他说，他每天要看十七次表。"},{"t":"n","text":"他说，医院的粥很淡，他喝完了，因为不吃会更慢。"},{"t":"n","text":"他说这些的时候，语气一直很平。平到你觉得他在念一份写好的稿子。"},{"t":"n","text":"然后他停了一下。"},{"t":"c","id":"baiyu","text":"出院那天，有个人来接我。"},{"t":"n","text":"他把手里的空罐子换了一只手。"},{"t":"c","id":"baiyu","text":"她带了外套，洗过，叠得很平。"},{"t":"n","text":"他说「她」的时候，没有解释是谁。"},{"t":"c","id":"baiyu","text":"上车以后，她跟我说，我们谈谈。"},{"t":"c","id":"baiyu","text":"我跟她说，等我忙完这一阵。"},{"t":"n","text":"风大了一点。床单被吹得啪啪响。"},{"t":"c","id":"baiyu","text":"她问我，哪一阵。"},{"t":"n","text":"他停在这里，停了很久。"},{"t":"n","text":"你以为他会往下说。他没有。"},{"t":"c","id":"baiyu","text":"后来就没有后来了。"},{"t":"n","text":"他把空罐子捏了一下，铝皮凹进去一个坑。"},{"t":"n","text":"他看着楼下的车流，没有看你。"},{"t":"c","id":"baiyu","text":"所以我现在做什么，都留三分。"},{"t":"n","text":"你把这三个字在心里过了一遍。留三分。"},{"t":"n","text":"方案留三分余地，话留三分不说，人留三分不靠近。"},{"t":"n","text":"不是清高。是他不敢把哪一样东西，放到收不回来的地方。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问他「你后悔吗」","hint":"问到底 · 关系会近","eff":{"aff":8.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你问他：「你后悔吗。」"},{"t":"n","text":"他想了很久，久到你以为他不会回答。"},{"t":"n","text":"楼下又有一辆救护车进来，红灯转了一圈，照在他脸上。"},{"t":"c","id":"baiyu","text":"后悔。但后悔没用。"},{"t":"n","text":"他转过头看你。"},{"t":"c","id":"baiyu","text":"后悔这个东西，只能拿来改下一次。改不了上一次。"},{"t":"n","text":"他说：「你还年轻。别学我。」"},{"t":"n","text":"你说：「你也不老。」"},{"t":"n","text":"他愣了一下。"},{"t":"n","text":"然后他笑了一下，很轻，只有嘴角动。"},{"t":"c","id":"baiyu","text":"谢谢。"},{"t":"n","text":"他说这两个字的时候，声音比刚才低了一点。他把外套往你肩上按了一下，又收回去。"},{"t":"n","text":"你想说，你不是在安慰他。你是真的这么觉得。"},{"t":"n","text":"但你没有说。有些话说出来，就太重了。"}]},{"label":"B","text":"说自己其实很害怕","hint":"说真话 · 压力 ↓","eff":{"aff":6.0,"happy":3.0,"stress":-3.0},"reply":[{"t":"n","text":"你说，你其实很怕。"},{"t":"n","text":"你说，你怕自己停下来就会被超过。你怕别人觉得你不行。你怕回家看见爸妈失望的脸。"},{"t":"n","text":"你说，你更怕的是，有一天你发现自己拼命保住的东西，其实没那么重要。"},{"t":"n","text":"你说到最后，声音有点抖。"},{"t":"n","text":"他没有打断你。"},{"t":"n","text":"他一直看着楼下，等你说完，才转过头。"},{"t":"c","id":"baiyu","text":"这些怕，我都有过。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"现在也有。"},{"t":"n","text":"你说：「那你怎么撑过来的。」"},{"t":"n","text":"他把空罐子放在栏杆上，罐子晃了一下，没倒。"},{"t":"c","id":"baiyu","text":"没撑过来。"},{"t":"n","text":"你看着他。"},{"t":"c","id":"baiyu","text":"我是撑到某一天，发现自己已经不需要撑了。那不是撑过来的，是耗过去的。"},{"t":"n","text":"他说完，补了一句："},{"t":"c","id":"baiyu","text":"怕不丢人。装作不怕才丢人。"},{"t":"n","text":"你说：「那你在会上，不也是装作不怕。」"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"baiyu","text":"那是工作。工作里可以装。生活里不行。"}]},{"label":"C","text":"岔开话题，问他为什么还不下班","hint":"不越界 · 保持距离","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"你问他，这么晚了，为什么还不下班。"},{"t":"n","text":"他说：「等你这一批人都走了，我就走。」"},{"t":"n","text":"你笑他像班主任。"},{"t":"n","text":"他也笑：「差不多。」"},{"t":"n","text":"你们笑了一下，气氛松了。"},{"t":"n","text":"风还是那么大。床单被吹得贴在绳子上，又松开。"},{"t":"n","text":"他看了看表。"},{"t":"c","id":"baiyu","text":"十点四十。你该回去了。"},{"t":"n","text":"你说：「你先回。」"},{"t":"c","id":"baiyu","text":"我送你到楼下。"}]}]},{"t":"block","when":"flag1","steps":[{"t":"n","text":"临走前，他把那罐空咖啡扔进垃圾桶。"},{"t":"n","text":"罐子撞在桶底，响了一声。"},{"t":"n","text":"他站在垃圾桶旁边，忽然说："},{"t":"c","id":"baiyu","text":"今天这些话，不是顾问说的。"},{"t":"n","text":"他看着你，视线很稳。"},{"t":"n","text":"风把他的头发吹乱了一点，他没有去理。"},{"t":"c","id":"baiyu","text":"是一个也住过院的人，跟你说的。"},{"t":"n","text":"他没有等你回答。"},{"t":"n","text":"他伸手，把门推开，先走了。"},{"t":"n","text":"门在他身后慢慢合上，没有关严，留了一条缝。"},{"t":"n","text":"外套还在你身上。你低头，闻了一下袖口。"},{"t":"n","text":"那个味道你后来记了很多年。"}]},{"t":"block","when":"low","minAff":60,"steps":[{"t":"n","text":"你上了天台。"},{"t":"n","text":"他站在栏杆边，看见你，把外套递过来。"},{"t":"c","id":"baiyu","text":"披着。夜里风大。"},{"t":"n","text":"你接过来。他没有再说话。"},{"t":"n","text":"你们并排站着。楼下的红灯亮着，一辆救护车开走了，声音拖得很长。"},{"t":"n","text":"你等他开口。"},{"t":"n","text":"他没有开口。"},{"t":"n","text":"你忽然意识到，他可能本来是想说的。只是走到这一步，又收了回去。"},{"t":"n","text":"他看了看表。"},{"t":"c","id":"baiyu","text":"十点二十了。早点回去。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他把外套从你肩上拿回去，搭在手臂上。"},{"t":"n","text":"他推开消防门，让你先下。"},{"t":"n","text":"楼梯间很安静。你们一前一后地走，谁也没有说话。"},{"t":"n","text":"到八楼，他停下。"},{"t":"c","id":"baiyu","text":"明天不用早到。你的报告我看了，写得不错。"},{"t":"n","text":"他说完，转身往病房区走。"},{"t":"n","text":"你站在楼梯口，看着他的背影。"},{"t":"n","text":"走廊尽头的灯有一盏坏了，一闪一闪。"}]}],"id":"baiyu_12"}]},{"id":"ch3","title":"第三章 · 项目结束","scenes":[{"no":13,"title":"结项会","week":55,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"结项会开了两个小时。"},{"t":"n","text":"方案全部通过。最后一页的验收栏上，客户方的负责人签了字。"},{"t":"n","text":"签字的时候，他把笔递给你。"},{"t":"n","text":"你说：「你先签。」"},{"t":"n","text":"他说：「我是顾问，你是执行。你签前面。」"},{"t":"n","text":"你在那一栏写下自己的名字。手有点抖。"},{"t":"n","text":"签完，他接过去，签在下一行。"},{"t":"n","text":"两个名字离得很近，中间只隔了一条横线。"},{"t":"n","text":"会议室里有人鼓掌，鼓得很稀。项目做了大半年，大家都累了。"},{"t":"n","text":"负责人合上文件夹，转向白屿。"},{"t":"n","text":"他说：「白老师，下个阶段的运营，还想请您继续。」"},{"t":"n","text":"白屿摇头。"},{"t":"c","id":"baiyu","text":"合约到周五。"},{"t":"n","text":"负责人说：「我们可以加钱。」"},{"t":"c","id":"baiyu","text":"不是钱的事。"},{"t":"n","text":"他把自己的那份文件收进包里。"},{"t":"c","id":"baiyu","text":"一个项目做完了，我就该走了。这是我给自己定的规矩。"},{"t":"n","text":"负责人还想说什么，周姐拉了他一下。"},{"t":"n","text":"散会的时候，负责人跟他握手，说：「白老师，以后有项目，还找您。」"},{"t":"n","text":"白屿说：「好。」"},{"t":"n","text":"他把手抽回来，在裤子上擦了一下。"},{"t":"n","text":"不是嫌脏。是手心有汗。"},{"t":"n","text":"你看见了。他好像也知道你看见了。"},{"t":"n","text":"会议散了。"},{"t":"n","text":"你在走廊里等他。"},{"t":"n","text":"他出来的时候，手里抱着一个纸箱，里面是这半年攒下的资料。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问他接下来去哪","hint":"问未来 · 心会乱","eff":{"aff":5.0,"eq":2.0,"happy":-1.0},"reply":[{"t":"n","text":"你问他，接下来去哪。"},{"t":"n","text":"他把纸箱换了个姿势抱着。"},{"t":"c","id":"baiyu","text":"南边。一个旧粮仓，想改成小剧场。"},{"t":"n","text":"你说：「听起来不像能赚钱的项目。」"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"baiyu","text":"是不太赚。但那个房子很好。五十年代的，砖是手工的，屋顶有六个通风口。"},{"t":"n","text":"他说起那个房子的时候，语速比平时快了一点。"},{"t":"n","text":"他说，那个项目他想了三年。三年前他路过那里，门是锁着的，他从窗缝往里看，看见一地麦壳。"},{"t":"n","text":"「当时就想，这个空间要是能让人坐在里面听点什么，会很好。」"},{"t":"n","text":"你说：「那你为什么现在才去。」"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"因为以前觉得，还有时间。"}]},{"label":"B","text":"说「那你还会来吗」","hint":"问一句 · 会得到真话","eff":{"aff":5.0,"happy":2.0},"reply":[{"t":"n","text":"你问他，还会不会来。"},{"t":"n","text":"他抱着纸箱，站在走廊中间。"},{"t":"c","id":"baiyu","text":"项目上的事，随时可以问。"},{"t":"n","text":"你说：「我问的不是项目。」"},{"t":"n","text":"走廊里有同事经过，推着一辆装满样品的推车。轮子在地面上发出很响的声音。"},{"t":"n","text":"等推车过去了，他才开口。"},{"t":"c","id":"baiyu","text":"我不知道。"},{"t":"n","text":"他说得很坦白。"},{"t":"c","id":"baiyu","text":"我这个人，走了就是走了。以前也有人说，走了也可以联系。后来都没有联系。"},{"t":"n","text":"你说：「那是他们。」"},{"t":"n","text":"他看了你一眼。"},{"t":"c","id":"baiyu","text":"你不一样。"},{"t":"n","text":"他补了一句：「所以我才更不敢随便答应。」"}]},{"label":"C","text":"什么都不问","hint":"不问 · 装作没事","eff":{"aff":2.0,"stress":2.0,"happy":-2.0},"reply":[{"t":"n","text":"你什么也没问。"},{"t":"n","text":"你帮他把纸箱上的胶带按紧了一点。"},{"t":"n","text":"他说谢谢。"},{"t":"n","text":"你们一起走到电梯口。电梯来了，他进去，按住开门键。"},{"t":"c","id":"baiyu","text":"不上？"},{"t":"n","text":"你说你还有事。"},{"t":"n","text":"他点头，松开手。门合上。"},{"t":"n","text":"你站在电梯口，看着楼层数字往下跳。"},{"t":"n","text":"你其实没有事。"}]}]},{"t":"n","text":"那天晚上，你上了天台。"},{"t":"n","text":"这里的天台上只有两个空调外机，和一盏坏了的灯。"},{"t":"n","text":"你站在栏杆边，看着楼下的路。"},{"t":"n","text":"过了一会儿，门响了。"},{"t":"n","text":"白屿上来，手里拿着两罐汽水。"},{"t":"n","text":"他把一罐递给你。"},{"t":"c","id":"baiyu","text":"庆祝一下。不管选哪个，都值得。"},{"t":"n","text":"你接过汽水。罐子很凉。"},{"t":"n","text":"是橘子味的。你不喜欢橘子味，但你还是喝完了。"},{"t":"n","text":"你们并排站着，谁也没有说话。"},{"t":"n","text":"喝到一半，他忽然开口。"},{"t":"c","id":"baiyu","text":"周五下午，我收拾东西。"},{"t":"n","text":"你说：「需要帮忙吗。」"},{"t":"n","text":"他摇头。"},{"t":"c","id":"baiyu","text":"东西不多。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"但你可以来。"},{"t":"n","text":"你说好。"},{"t":"n","text":"汽水喝完，他把两个空罐子叠在一起，捏扁，拿在手里。"},{"t":"c","id":"baiyu","text":"走了。"},{"t":"n","text":"他下楼了。"},{"t":"n","text":"你在天台上站到很晚。城市的灯一盏一盏地灭。"}],"id":"baiyu_13"},{"no":14,"title":"他的桌子","week":56,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"他说的「收拾东西」，真的只有一箱。"},{"t":"n","text":"一个马克杯，白的，杯身上印着一家已经倒闭的公司的 logo。"},{"t":"n","text":"一支笔，黑色，笔帽上有一道很浅的划痕。"},{"t":"n","text":"一本笔记本，硬壳，深蓝色，边角磨白了。"},{"t":"n","text":"一个充电器，一副耳机。"},{"t":"n","text":"他把这些东西一件一件放进纸箱。"},{"t":"n","text":"那间小会议室不是他的办公室。他只是每周来两次，用两个小时。桌上连名牌都没有。"},{"t":"n","text":"但你把这三样东西看了很久。"},{"t":"n","text":"原来一个人在一个地方待了大半年，留下的痕迹可以这么少。"},{"t":"n","text":"他把白板擦干净。擦到最后，白板上什么也没有了，只剩一层擦不掉的水痕。"},{"t":"n","text":"角落里有半个字，是他很久以前写的，被后来的内容盖住了。"},{"t":"n","text":"看起来像「慢」。"},{"t":"n","text":"他看了一眼，没有擦。"},{"t":"n","text":"他站在白板前看了一会儿，把板擦放回槽里。"},{"t":"n","text":"你蹲下来，帮他整理纸箱。"},{"t":"n","text":"笔记本翻开了一条缝。里面夹着一张照片。"},{"t":"n","text":"照片是打印的，A4 纸裁下来的，边缘不齐。"},{"t":"n","text":"照片上是七八个人，站在一片空地上，背后是一栋没盖完的楼。"},{"t":"n","text":"他站在中间，穿一件浅色的短袖衬衫，笑得很大。"},{"t":"n","text":"那时候他瘦，头发也更黑，眉眼还没现在这么沉。"},{"t":"n","text":"照片右下角有一行很小的字，是手写的日期。旁边还有两个字：「沈迟」。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问他这是谁","hint":"问一句 · 会听到答案","eff":{"aff":5.0,"happy":-1.0,"eq":1.0},"reply":[{"t":"n","text":"你问：「沈迟是谁。」"},{"t":"n","text":"他没有立刻回答。"},{"t":"n","text":"他把照片接过去，看了一眼，才开口。"},{"t":"c","id":"baiyu","text":"以前一起做项目的人。"},{"t":"n","text":"他指着照片右边。"},{"t":"c","id":"baiyu","text":"这张其实有她。被前面这个人挡住了，只露了半张脸。"},{"t":"n","text":"你凑过去看。确实，在最右边，有一只手，和一截袖子。"},{"t":"c","id":"baiyu","text":"她那时候总说，拍照不要站在边上。站在边上会被裁掉。"},{"t":"n","text":"他说完，把照片翻过来，背面朝上。"},{"t":"n","text":"你说：「那你还站在中间。」"},{"t":"n","text":"他愣了一下。"},{"t":"c","id":"baiyu","text":"后来就没人提醒我了。"},{"t":"n","text":"他把照片夹回笔记本里，动作很轻。"}]},{"label":"B","text":"不问","hint":"不问 · 让他留着","eff":{"aff":3.0,"happy":1.0},"reply":[{"t":"n","text":"你没有问。"},{"t":"n","text":"你把笔记本合上，放回纸箱。"},{"t":"n","text":"他看了你一眼，好像有点意外。"},{"t":"n","text":"过了一会儿，他自己说了。"},{"t":"c","id":"baiyu","text":"那是我二十七岁。第一个自己带的项目。"},{"t":"n","text":"他说，那栋楼最后没盖完。资金断了，停工，五年后拆掉，那块地现在是一个停车场。"},{"t":"n","text":"你说：「那你还会留着照片。」"},{"t":"c","id":"baiyu","text":"照片是照片。楼是楼。"},{"t":"n","text":"他把纸箱的盖折起来。"},{"t":"c","id":"baiyu","text":"而且，那几年虽然什么都没成，但人是齐的。"}]},{"label":"C","text":"说「你以前挺好看」","hint":"玩笑一句 · 气氛松","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你说：「你以前挺好看。」"},{"t":"n","text":"他看了看照片，又看了看你。"},{"t":"c","id":"baiyu","text":"以前？"},{"t":"n","text":"你说：「现在也还行。就是老了一点。」"},{"t":"n","text":"他笑出声来。那一声很短，但确实是笑。"},{"t":"c","id":"baiyu","text":"你这张嘴，在会上怎么那么笨。"},{"t":"n","text":"你说：「在会上我怕说错。」"},{"t":"c","id":"baiyu","text":"在这儿不怕？"},{"t":"n","text":"你说：「在这儿说错了，你也不会扣我绩效。」"},{"t":"n","text":"他笑着摇了摇头。"},{"t":"c","id":"baiyu","text":"你倒是把我的边界记得很清楚。"}]}]},{"t":"n","text":"纸箱装好，他用胶带封了口。"},{"t":"n","text":"封完，他把那支笔拿了出来，放在桌上。"},{"t":"c","id":"baiyu","text":"这个给你。"},{"t":"n","text":"你说：「笔不好用。」"},{"t":"n","text":"他笑：「是不好用。写快了会断墨。」"},{"t":"n","text":"他把笔推过来一点。"},{"t":"c","id":"baiyu","text":"笔帽上这道划痕，是我自己磕的。摔在工地上。"},{"t":"n","text":"你说：「那你留着。」"},{"t":"c","id":"baiyu","text":"我有两支。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"baiyu","text":"另一支是我买的第一支好笔。花了我半个月工资。"},{"t":"n","text":"你说：「那支呢。」"},{"t":"c","id":"baiyu","text":"丢了。"},{"t":"n","text":"他把笔往你手边又推了一点。"},{"t":"c","id":"baiyu","text":"这个别丢。"},{"t":"n","text":"你把笔握在手里。笔身是温的，他握了有一会儿。"},{"t":"n","text":"他把纸箱抱起来。"},{"t":"n","text":"你们一起下楼。他先去行政处还门禁卡。"},{"t":"n","text":"行政的小姑娘说：「白老师，以后还来吗。」"},{"t":"n","text":"他想了想，说：「项目上的事，会来。」"},{"t":"n","text":"这句话说得很轻。"},{"t":"n","text":"走出写字楼，他站在门口，抬头看了一眼这栋楼。"},{"t":"c","id":"baiyu","text":"比我想的矮。"},{"t":"n","text":"你说：「你在这儿待了大半年。」"},{"t":"c","id":"baiyu","text":"大半年，没上过顶楼。"},{"t":"n","text":"他抱着纸箱往路边走。"},{"t":"n","text":"走了几步，他回头。"},{"t":"c","id":"baiyu","text":"明天开馆。你会很忙。"},{"t":"n","text":"你说：「你会来吗。」"},{"t":"n","text":"他没有直接答。"},{"t":"c","id":"baiyu","text":"我会在。"}],"id":"baiyu_14"},{"no":15,"title":"开馆日","week":56,"bg":"auditorium","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"开馆那天来了很多人。"},{"t":"n","text":"门口的横幅是红底白字，风一吹就鼓起来，字被吹得变形。"},{"t":"n","text":"有媒体，有附近的居民，有带着小孩来的年轻父母。"},{"t":"n","text":"阅览区在二楼西侧。八百平方米，四面开窗，放了长桌和矮书架。"},{"t":"n","text":"十点开门，十点二十，里面就坐满了人。"},{"t":"n","text":"有个老人坐在靠窗的位置看报纸，看了很久。有个小孩趴在地上看绘本，鞋脱在一边。"},{"t":"n","text":"你在楼下跑来跑去。对讲机里不断有人叫你的名字。"},{"t":"n","text":"十一点，你才有空喝一口水。"},{"t":"n","text":"你抬头，看见白屿在门口。"},{"t":"n","text":"他站在门外面，没有进来。"},{"t":"n","text":"他穿的是便装——深灰色的夹克，里面一件白衬衫，没有领带。"},{"t":"n","text":"他的鞋边沾了一点灰，是从工地那边一路走过来的。"},{"t":"n","text":"他没有拍。"},{"t":"n","text":"他把手插在口袋里，看着门里。"},{"t":"n","text":"像一个路过的人。"},{"t":"n","text":"你走过去。"},{"t":"n","text":"他看见你，往后退了半步，让出门的位置。"},{"t":"c","id":"baiyu","text":"忙着。"},{"t":"n","text":"你说：「你进来看看。」"},{"t":"n","text":"他摇头。"},{"t":"c","id":"baiyu","text":"我看过了。"},{"t":"n","text":"你说：「什么时候。」"},{"t":"c","id":"baiyu","text":"早上七点。门没锁。"},{"t":"n","text":"他说，他在阅览区坐了一会儿。没有人，窗户开着，风把桌上的登记簿翻了两页。"},{"t":"c","id":"baiyu","text":"很好。"},{"t":"n","text":"他只说了两个字。"},{"t":"n","text":"你等着他往下说。"},{"t":"n","text":"他没有往下说。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"留他","hint":"留一句 · 关系会变","eff":{"aff":5.0,"happy":2.0},"reply":[{"t":"n","text":"你说：「那你别走。等忙完，我请你吃饭。」"},{"t":"n","text":"他看了你一会儿。"},{"t":"c","id":"baiyu","text":"今天不行。"},{"t":"n","text":"你问为什么。"},{"t":"n","text":"他把手从口袋里拿出来，指了指门口外面。"},{"t":"c","id":"baiyu","text":"我站在这里，别人会问，这个人是谁。"},{"t":"n","text":"你说：「你是这个项目的顾问。」"},{"t":"c","id":"baiyu","text":"从昨天起，不是了。"},{"t":"n","text":"他说得很平静。"},{"t":"c","id":"baiyu","text":"今天这个场子，是你的。我站在里面，会分掉一部分。"},{"t":"n","text":"你说：「我不在乎。」"},{"t":"c","id":"baiyu","text":"我在乎。"},{"t":"n","text":"他补了一句，声音低了一点："},{"t":"c","id":"baiyu","text":"你花了半年做这件事。别让它变成别的什么。"}]},{"label":"B","text":"让他走","hint":"不挽留 · 各自体面","eff":{"aff":3.0,"stress":1.0,"happy":-2.0},"reply":[{"t":"n","text":"你说：「那你路上小心。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"baiyu","text":"有事发消息。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他转身走了两步，又回来。"},{"t":"c","id":"baiyu","text":"对了。"},{"t":"n","text":"他从口袋里拿出一张纸，折了四折，递给你。"},{"t":"n","text":"你打开。是一张手写的清单。"},{"t":"n","text":"上面列了六条：开馆后第一个月的运营重点。"},{"t":"n","text":"第一条：前两周不要改任何动线，先看人怎么走。"},{"t":"n","text":"第二条：阅览区的椅子，坏一把换一把，不要凑合。"},{"t":"n","text":"第六条：累的时候，关一天门也可以。"},{"t":"n","text":"你抬头。他已经走到路口了。"}]},{"label":"C","text":"问他「你满意吗」","hint":"问一句 · 会听到真话","eff":{"aff":6.0,"happy":3.0,"eq":1.0},"reply":[{"t":"n","text":"你问他：「你满意吗。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"baiyu","text":"不满意。"},{"t":"n","text":"你愣住。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"baiyu","text":"「这行做久了，看什么都能挑出毛病。那边的导视牌，字太小。二楼的光，下午会偏。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"baiyu","text":"但我今天早上坐在那儿，听见楼下有人说话，有人在笑。我想，这个房子活了。"},{"t":"n","text":"他看着门里。"},{"t":"c","id":"baiyu","text":"一个项目做完，能看见有人用它，就算成了。"},{"t":"n","text":"你说：「那你为什么站在外面。」"},{"t":"n","text":"他没有回答。"},{"t":"n","text":"过了几秒，他说："},{"t":"c","id":"baiyu","text":"因为里面已经不需要我了。"}]}]},{"t":"n","text":"下午两点，人少了一些。"},{"t":"n","text":"你从二楼下来，门口已经没有人了。"},{"t":"n","text":"地上有一张被踩过的宣传单。"},{"t":"n","text":"你把它捡起来，扔进垃圾桶。"},{"t":"n","text":"手机响了。是白屿。"},{"t":"n","text":"他只发了一条：「明天下午三点的票。」"},{"t":"n","text":"你盯着这条消息看了很久。"},{"t":"n","text":"你没有回。"},{"t":"n","text":"你走到门口，站在他早上站过的位置。"},{"t":"n","text":"风从街口吹过来，把横幅吹得啪啪响。"},{"t":"n","text":"从这里往里看，正好能看见二楼阅览区的窗。"},{"t":"n","text":"窗边坐着那个看报纸的老人。"}],"id":"baiyu_15"},{"no":16,"title":"天台 / 车站","week":57,"bg":"rooftop_sunset","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"他约你六点，在写字楼天台。"},{"t":"n","text":"那栋楼他待了大半年，从来没上去过。这是他第一次。"},{"t":"n","text":"你上去的时候，他已经在栏杆边站着了。"},{"t":"n","text":"西装外套脱了，搭在栏杆上。衬衫袖子卷起来，领带松了，挂在脖子上。"},{"t":"n","text":"他手里没有咖啡。这次什么都没有。"},{"t":"n","text":"风很大，把楼下的旗子吹得响。"},{"t":"n","text":"他看见你，笑了一下。"},{"t":"c","id":"baiyu","text":"我三十二了。"},{"t":"n","text":"他说。"},{"t":"c","id":"baiyu","text":"再不去，就来不及了。"},{"t":"n","text":"你说：「去南边。」"},{"t":"n","text":"他点头。"},{"t":"c","id":"baiyu","text":"粮仓那个项目。下周进场，工期一年半。"},{"t":"n","text":"你说：「一年半。」"},{"t":"c","id":"baiyu","text":"可能更久。那种老房子，拆开看才知道里面什么样。"},{"t":"n","text":"他说着，眼睛看着远处。"},{"t":"n","text":"那是你第一次看见他讲一件事的时候，不看人。"},{"t":"n","text":"他说了一会儿，停下来。"},{"t":"c","id":"baiyu","text":"我跟你说过，我三十岁那年住过一次院。"},{"t":"n","text":"你说记得。"},{"t":"n","text":"他把手放在栏杆上，手指敲了两下。"},{"t":"c","id":"baiyu","text":"出院那天，有个人来接我。"},{"t":"n","text":"这一次，他往下说了。"},{"t":"c","id":"baiyu","text":"她叫沈迟。"},{"t":"n","text":"他说，她带了外套，洗过，叠得很平。"},{"t":"n","text":"他说，上车以后她说，我们谈谈。他说，等我忙完这一阵。"},{"t":"n","text":"他说，她问，哪一阵。"},{"t":"n","text":"他说，他没有答上来。"},{"t":"n","text":"他说，三个月后她调走了。他是在别人嘴里知道的。"},{"t":"n","text":"他说，他打了很多字，都删了。"},{"t":"n","text":"他说，两年后搬家，他把那个保温桶扔了。"},{"t":"n","text":"他说这些的时候，语速一直很平。"},{"t":"n","text":"但说到「保温桶」的时候，他停了一下。"},{"t":"c","id":"baiyu","text":"扔的时候，桶底有一圈水锈。洗不掉。"},{"t":"n","text":"他转过头看你。"},{"t":"c","id":"baiyu","text":"所以我做什么，都留三分。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"baiyu","text":"你别学我。"},{"t":"n","text":"你没有说话。"},{"t":"n","text":"风把两个人的头发都吹乱了。"},{"t":"n","text":"过了一会儿，你问他：「合作项目结束了？」"},{"t":"n","text":"他看着你。"},{"t":"c","id":"baiyu","text":"上周就结了。从今天起，我不是你的项目顾问。"},{"t":"n","text":"他说得很平静，像在说一件早就想好的事。"},{"t":"c","id":"baiyu","text":"合约到昨天为止。我今天上午去把最后一张单子签了。"},{"t":"n","text":"他从口袋里拿出一张纸，展开。"},{"t":"n","text":"是合约的最后一页，右下角盖着章，日期是昨天。"},{"t":"n","text":"他把它折好，放回口袋。"},{"t":"c","id":"baiyu","text":"签完字，我在楼下站了一会儿。"},{"t":"n","text":"你问他想什么。"},{"t":"c","id":"baiyu","text":"想我这两年，是不是白过了。"},{"t":"n","text":"你说：「所以你才敢站在这儿。」"},{"t":"n","text":"他愣了一下。"},{"t":"n","text":"然后他笑了。"},{"t":"c","id":"baiyu","text":"对。"},{"t":"n","text":"他笑得很轻，但眼睛里有东西亮了一下。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把话说出口","hint":"说出口 · 关系会变","eff":{"aff":8.0,"happy":6.0,"flag2":true,"lover":true},"reply":[{"t":"n","text":"你说，你不想只做他带过的人。"},{"t":"n","text":"他没有立刻回答。"},{"t":"n","text":"他看了你很久，久到风把两个人的头发都吹乱了。"},{"t":"n","text":"他开口的时候，声音比平时低。"},{"t":"c","id":"baiyu","text":"我比你大十岁。"},{"t":"n","text":"你说你知道。"},{"t":"c","id":"baiyu","text":"而且我马上要走。"},{"t":"n","text":"你说你知道。"},{"t":"n","text":"他沉默了。"},{"t":"n","text":"你听见楼下有人在喊什么，听不清。"},{"t":"n","text":"他把手从栏杆上拿开，转过身，面对你。"},{"t":"c","id":"baiyu","text":"你知道，还说。"},{"t":"n","text":"你说：「因为不说，就跟你一样了。」"},{"t":"n","text":"他的表情变了。变得很轻，又很重。"},{"t":"n","text":"他低下头，笑了一下。"},{"t":"c","id":"baiyu","text":"你这一句，够我记很久。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"baiyu","text":"那就……试试。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"但我不保证什么。"},{"t":"n","text":"你说：「你不用保证。」"},{"t":"n","text":"他伸出手。停在半空。"},{"t":"n","text":"那只手你见过很多次——递文件，递水，递外套，递名片。"},{"t":"n","text":"这一次他递的是空的。"},{"t":"n","text":"你握住了。"},{"t":"n","text":"他的手很凉，掌心有一点汗。"},{"t":"n","text":"他握得不紧，像在等你可以随时抽回去。"},{"t":"n","text":"你没有抽。"},{"t":"n","text":"他忽然笑了一下，很轻。"},{"t":"c","id":"baiyu","text":"这次，我没留三分。"}]},{"label":"B","text":"守住分寸","hint":"留在原地 · 更长久","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你说，谢谢他这半年。"},{"t":"n","text":"他点点头，像早就知道你会这么说。"},{"t":"c","id":"baiyu","text":"有事发消息。别客气，也别太客气。"},{"t":"n","text":"你说好。"},{"t":"n","text":"你们又站了一会儿。"},{"t":"n","text":"他说：「我该走了。」"},{"t":"n","text":"你说：「我送你到楼下。」"},{"t":"n","text":"他说不用。"},{"t":"n","text":"他拿起外套，抖了一下，穿上。"},{"t":"n","text":"走到门口，他回头。"},{"t":"c","id":"baiyu","text":"你做得很好。"},{"t":"n","text":"你说：「跟你学的。」"},{"t":"n","text":"他笑了一下，推门下楼了。"}]},{"label":"C","text":"送他走","hint":"不说不问 · 到此为止","eff":{"aff":2.0,"stress":2.0,"happy":-2.0},"reply":[{"t":"n","text":"你什么也没说。"},{"t":"n","text":"你帮他把箱子提到楼下。"},{"t":"n","text":"箱子不重，但很占地方。你侧着身子下楼梯。"},{"t":"n","text":"车停在路边。"},{"t":"n","text":"他把箱子放进后备箱，关上。"},{"t":"n","text":"他站在车门口，看了你一眼。"},{"t":"n","text":"你也没有说话。"},{"t":"n","text":"他上车。隔着玻璃，冲你抬了抬下巴。"},{"t":"n","text":"车开走了。"},{"t":"n","text":"你在原地站了一会儿，才想起来自己没吃晚饭。"}]}]},{"t":"n","text":"天台的门在身后关上。"},{"t":"n","text":"你低头，看见地上有一支笔。"},{"t":"n","text":"是你放在口袋里的那支。你不知道它什么时候掉的。"},{"t":"n","text":"你把它捡起来。"},{"t":"n","text":"笔帽上有一道很浅的划痕，被路灯照出一条白线。"},{"t":"n","text":"你把它放进口袋。"},{"t":"n","text":"楼下有人在按喇叭。"},{"t":"n","text":"你站在天台上，看着城市的灯一盏一盏亮起来。"},{"t":"block","when":"low","steps":[{"t":"n","text":"你站在天台门口，没有进去。"},{"t":"n","text":"门开着一条缝。你看见他站在栏杆边，背对着你。"},{"t":"n","text":"他好像听见了动静，回过头。"},{"t":"n","text":"他看见你，冲你点了点头。"},{"t":"n","text":"你走进去，站在离他三四步的地方。"},{"t":"n","text":"你们隔着半个天台，谁也没有先开口。"},{"t":"n","text":"风把栏杆上的外套吹得动了一下。他伸手按住。"},{"t":"n","text":"过了很久，他说：「走了。保重。」"},{"t":"n","text":"你说：「保重。」"},{"t":"n","text":"他拿起外套，从你身边走过去。"},{"t":"n","text":"门在他身后合上。"}]}],"id":"baiyu_16","judgeAfter":true}]},{"id":"finale","title":"终章 · 三种结局","scenes":[{"no":17,"title":"这次，他没留三分","week":60,"bg":"livingroom_night","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"他去了另一座城市。你们异地了一年半。"},{"t":"n","text":"头一年很难。"},{"t":"n","text":"他忙，你也忙。视频常常约在晚上十一点。"},{"t":"n","text":"有时候接通了，两个人都累得不想说话，就开着，各做各的。"},{"t":"n","text":"他那边总是同一面墙。粮仓的红砖，露出一小块，他没让人补。"},{"t":"n","text":"他把手机架在一个水杯上，角度总是歪的。你说了三次，他还是歪。"},{"t":"n","text":"你去过他那里一次。坐高铁四个小时，再转一趟公交。"},{"t":"n","text":"工地很吵。他戴着安全帽，站在脚手架下面，跟一个老师傅比划屋顶的通风口。"},{"t":"n","text":"他看见你，愣了一下，然后走过来。"},{"t":"n","text":"他摘下安全帽，头发被压出一道印。"},{"t":"c","id":"baiyu","text":"你怎么来了。"},{"t":"n","text":"你说：「来看看。」"},{"t":"n","text":"他站在那里，看了你一会儿，忽然伸手，把安全帽扣在你头上。"},{"t":"c","id":"baiyu","text":"戴上。上面在掉灰。"},{"t":"n","text":"帽子太大，一直往下滑。"},{"t":"n","text":"他伸手扶了一下，手在你脸侧停了一秒，又收回去。"},{"t":"n","text":"那天他带你从一楼走到三楼。讲哪面墙要留，哪个窗户要开，哪个角落下午会有光。"},{"t":"n","text":"他讲得很细。你听着，觉得他比在这座城市的时候，话多了。"},{"t":"n","text":"也吵过一次架。"},{"t":"n","text":"那次他连着两周没打视频，只说「在赶工」。"},{"t":"n","text":"你在电话里说：「你又要留三分。」"},{"t":"n","text":"电话那头很安静。"},{"t":"n","text":"过了一会儿，他说：「我没有。」"},{"t":"n","text":"你说：「你有。」"},{"t":"n","text":"他没有再辩解。他说：「我明天给你打。」"},{"t":"n","text":"第二天，他没有打。"},{"t":"n","text":"第三天晚上，你手机响了。是视频。"},{"t":"n","text":"他坐在一间没装修完的屋子里，背后是裸露的墙。灯光很暗。"},{"t":"c","id":"baiyu","text":"我把机票改签了。"},{"t":"n","text":"你说：「改到哪天。」"},{"t":"c","id":"baiyu","text":"后天。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"baiyu","text":"我本来想等这面墙刷完。"},{"t":"n","text":"你说：「墙可以等。」"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"baiyu","text":"嗯。墙可以等。"},{"t":"n","text":"一年半后，他回来了。"},{"t":"n","text":"没有仪式。只是某天晚上，他发来一条消息：「我在你楼下。」"},{"t":"n","text":"你下去。"},{"t":"n","text":"他站在路灯下，手里拎着一个很小的行李箱。"},{"t":"n","text":"就是那个一直没有完全拆开的行李箱。"},{"t":"c","id":"baiyu","text":"那边的事做完了。"},{"t":"n","text":"你说：「然后呢。」"},{"t":"n","text":"他把箱子换到另一只手。"},{"t":"c","id":"baiyu","text":"然后，看你愿不愿意收留我。"},{"t":"n","text":"你说：「你不是有房子。」"},{"t":"c","id":"baiyu","text":"退了。"},{"t":"n","text":"你说：「工作呢。」"},{"t":"c","id":"baiyu","text":"交给别人了。我做顾问，本来就是做完就走。"},{"t":"n","text":"他说得很平静。"},{"t":"n","text":"但你看见他握着箱子把手的手，指节有点白。"},{"t":"n","text":"你说：「进来吧。」"},{"t":"n","text":"他站在门口，没有马上进来。"},{"t":"n","text":"他先把鞋在门口的地垫上蹭了两下。"},{"t":"n","text":"后来你们住在一起。"},{"t":"n","text":"他还是早起，还是把衬衫熨得很平，还是会在你加班的时候，把饭热在锅里。"},{"t":"n","text":"他有一个习惯一直没改：出门前一定要检查一遍门锁，检查两次。"},{"t":"n","text":"你问他为什么。"},{"t":"c","id":"baiyu","text":"习惯了。以前一个人住，锁坏了没人知道。"},{"t":"n","text":"有一点变了。"},{"t":"n","text":"他不再什么都留三分。"},{"t":"n","text":"方案还是留余地的。这一点他说改不了，也不该改。"},{"t":"n","text":"但你问他「你在想什么」的时候，他会说。"},{"t":"n","text":"你问他「你以后想怎么样」的时候，他也会说。"},{"t":"n","text":"有一次你问他，为什么。"},{"t":"n","text":"他正在洗碗，手上都是泡沫。"},{"t":"c","id":"baiyu","text":"留三分是给工作的。"},{"t":"n","text":"他把碗放进沥水架。"},{"t":"c","id":"baiyu","text":"给你，不用。"}],"quality":{"high":["你们的日子很安静。","安静到你有时候会觉得，遇见他之前的那几年，好像都在赶路。","周末他做饭。他做的菜不好吃，但很准时。","有一年冬天，你们在阳台上晒被子。他忽然说：「我以前以为，日子是要过成什么样子的。」","你问他现在呢。","他说：「现在就是过。」"],"mid":["他还是不太会说甜话。","但你说过的每一件小事，他都记得。","你随口说过一次「那家店的面包好吃」，他下班就绕了三条街去买。","买回来的时候，面包有点压扁了。","他把袋子放在桌上，说：「下次我早点去。」"],"low":["他依然把很多事放在心里。","你有时候会想，自己是不是只认识了他的三分。","有一年他生病，你在旁边守着。他烧到三十八度，说了几句胡话。","他说了一句「对不起」，没有说对谁。","第二天他醒了，不记得。","你没有问。","有些门，他不推开，你也不推。你们就这样过下去，也过得下去。"]},"id":"baiyu_17","ending":"stay","endingName":"结局一 · 这次，他没留三分"},{"no":18,"title":"有些人教你长大（爱过 / 错过）","week":60,"bg":"izakaya_night","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"他走了。"},{"t":"n","text":"你们偶尔发消息，都是很短的。"},{"t":"n","text":"「最近怎么样。」「还行。你呢。」「也还行。」"},{"t":"n","text":"有些消息，你打完了，看一遍，删掉。有些消息，他打完了，也没有发出来。"},{"t":"n","text":"三年后，你出差去他的城市。"},{"t":"n","text":"你提前一天给他发消息：「我在你这边，有空吗。」"},{"t":"n","text":"他回：「有。明天晚上。」"},{"t":"n","text":"约在一家小馆子。不是他带你去的那个老街面馆，是另一个，离他住的地方近。"},{"t":"n","text":"店很小，桌子是木头的，桌角有一盏小灯。"},{"t":"n","text":"他比你先到。"},{"t":"n","text":"他瘦了一点，头发短了，鬓角的银灰多了一些。"},{"t":"n","text":"他穿一件深灰色的针织衫，不是西装。你一时有点不习惯。"},{"t":"n","text":"他站起来，替你把椅子拉开。"},{"t":"n","text":"坐下以后，两个人都不知道该从哪说起。"},{"t":"n","text":"他问你工作怎么样。你说了。他听完，点头。"},{"t":"n","text":"你问他项目怎么样。他说做完了，现在在做一个更小的，一所小学的图书室。"},{"t":"n","text":"菜上来，你们吃。中间有几段很长的沉默。"},{"t":"n","text":"不是尴尬的那种沉默。是两个人都不急着填满。"},{"t":"n","text":"他给你夹了一筷子菜，夹到一半停住，问：「你还吃辣吗。」"},{"t":"n","text":"你说吃。"},{"t":"n","text":"他把菜放进你碗里。"},{"t":"n","text":"这个动作他做得太自然，自然到两个人都愣了一下。"},{"t":"n","text":"过了一会儿，他低头继续吃，什么也没说。"},{"t":"n","text":"吃到一半，他忽然说：「那支笔，你还留着吗。」"},{"t":"n","text":"你说留着。"},{"t":"n","text":"他说：「还能写吗。」"},{"t":"n","text":"你说：「断墨。」"},{"t":"n","text":"他笑了。笑得很轻。"},{"t":"c","id":"baiyu","text":"我说过不好用。"},{"t":"n","text":"分开的时候，在店门口。"},{"t":"n","text":"街上有风，他把外套的扣子扣上一颗。"},{"t":"c","id":"baiyu","text":"你做得很好。"},{"t":"n","text":"你说：「跟你学的。」"},{"t":"n","text":"他笑了笑，说：「别学我。学点好的。」"},{"t":"n","text":"你说：「比如什么。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"baiyu","text":"比如，想说什么就说。"},{"t":"n","text":"他说完，自己沉默了一下。"},{"t":"n","text":"你看着他的侧脸。路灯从背后照过来，他的鬓角白得很明显。"},{"t":"n","text":"你想说点什么。"},{"t":"n","text":"他也好像想说点什么。"},{"t":"n","text":"最后你们都没有说。"},{"t":"n","text":"他伸手，很轻地，在你肩上拍了一下。"},{"t":"c","id":"baiyu","text":"回去吧。路上小心。"},{"t":"n","text":"他站在店门口，看你走到路口。"},{"t":"n","text":"你回头。他还站在那儿，抬手，示意你走。"},{"t":"n","text":"后来你听说他结婚了。"},{"t":"n","text":"对方是他在新城市认识的人。很安静，笑起来很好看。"},{"t":"n","text":"你没有去婚礼。你寄了一份礼，附了一张卡片。"},{"t":"n","text":"上面写着：「祝你这次，不用留三分。」"},{"t":"n","text":"他没有回。过了很久，他发来两个字：「谢谢。」"},{"t":"block","when":"hasFlag2","minAff":null,"steps":[{"t":"n","text":"你们试过。"},{"t":"n","text":"异地的那一年，你们都很努力。"},{"t":"n","text":"但有些事不是努力就够的。他忙起来会消失两周，你忙起来会忘记回消息。"},{"t":"n","text":"那一年春天，你们在电话里谈了一次。"},{"t":"n","text":"谈得很平静。谁也没有怪谁。"},{"t":"n","text":"他说：「是我不好。我以为我可以。」"},{"t":"n","text":"你说：「你已经很好了。」"},{"t":"n","text":"挂电话之前，他停了一会儿。"},{"t":"c","id":"baiyu","text":"你以后，别找像我这样的。"},{"t":"n","text":"你说：「我以后，会找一个愿意把话说完的。」"},{"t":"n","text":"他笑了一声。那一声里有很多东西。"},{"t":"n","text":"后来你们还是偶尔发消息。他结婚的时候，你寄了礼。"}]}],"quality":{"high":["你后来也遇到了很好的人。","你偶尔会想起他，像想起一个教会你走路的人。","有一次你在会上发言，说了一句「先把边界弄清楚」。说完你自己愣了一下。","那是他说过的话。"],"mid":["你们逢年过节发一条消息。","你换了工作，他换了城市，都没有告诉对方。","有一年春节，他发来一张照片。是一座小学校的图书室，窗户很大，光很好。","你回了一个「好看」。","他回了一个「嗯」。"],"low":["你一直留着那支笔。","笔帽上的划痕，像一道没说完的话。","你搬过两次家，换过三个抽屉。它一直在一个笔筒里。","你从来不用它。也从来不舍得扔。"]},"id":"baiyu_18","ending":"miss","endingName":"结局二 · 有些人教你长大（爱过 / 错过）"},{"no":19,"title":"你做得很好（师徒 / 知己）","week":60,"bg":"office_day","cast":["baiyu"],"steps":[{"t":"cast","list":["baiyu"],"focus":"baiyu"},{"t":"n","text":"你们做了一辈子的师徒，也做了一辈子的朋友。"},{"t":"n","text":"他每年生日，你会发一条消息。"},{"t":"n","text":"他每次都回：「谢谢。你也是。」"},{"t":"n","text":"不多一个字，也不少一个字。"},{"t":"n","text":"有一年他回了一句长的。"},{"t":"n","text":"他说：「今年在南边。房子旧，但屋顶高。」"},{"t":"n","text":"你回了三个字：「多穿点。」"},{"t":"n","text":"他回：「好。」"},{"t":"n","text":"有一年你忘了。过了三天才想起来，赶紧补了一条。"},{"t":"n","text":"他回：「我知道你忙。不用补。」"},{"t":"n","text":"你升职那年，给他打电话。"},{"t":"n","text":"电话响了很久才接。他那边很吵，有电钻的声音。"},{"t":"n","text":"你说：「我升了。」"},{"t":"n","text":"他在电话那头沉默了一会儿。"},{"t":"c","id":"baiyu","text":"我就知道。"},{"t":"n","text":"你说：「你就知道。」"},{"t":"c","id":"baiyu","text":"嗯。你做事的样子，一开始就看得出来。"},{"t":"n","text":"你笑了。你说：「那你当时还让我重做三遍。」"},{"t":"n","text":"他在电话那头也笑了。"},{"t":"c","id":"baiyu","text":"三遍算少的。我当年被人退过七遍。"},{"t":"n","text":"后来你带新人。"},{"t":"n","text":"你也会把文件夹放在他们桌上，说：「周三之前给我。」"},{"t":"n","text":"你也会在他们交上来的时候说：「第 7 条，重写。」"},{"t":"n","text":"新人问你：「白老师，你以前也这么严吗。」"},{"t":"n","text":"你说：「不是。我老师比我严。」"},{"t":"n","text":"新人问：「你老师是谁。」"},{"t":"n","text":"你说：「一个外面的人。」"},{"t":"n","text":"新人没听懂。你也没有解释。"},{"t":"n","text":"那个新人姓许，刚毕业，说话很快。"},{"t":"n","text":"有一次他把一份东西交上来，你翻了两页，合上。"},{"t":"n","text":"你说：「方向错了。重做。」"},{"t":"n","text":"他站在那儿，脸涨得通红。"},{"t":"n","text":"你看着他，忽然想起自己当年站在会议室门口的样子。"},{"t":"n","text":"你把文件夹推回去，说：「坐下。我告诉你错在哪。」"},{"t":"n","text":"那天你讲了四十分钟。"},{"t":"n","text":"讲完，他眼睛亮了一点。"},{"t":"n","text":"你忽然明白，白屿当年明明可以两句话打发你，为什么要花两个小时。"},{"t":"n","text":"你想起他，想起天台上的风，想起那杯没喝完的咖啡。"},{"t":"n","text":"你想起他递外套的时候说「披着，别逞强」。"},{"t":"n","text":"你想起他说「留三分」。"},{"t":"n","text":"下班以后，你给他发了一条消息：「我现在也带人了。」"},{"t":"n","text":"他回得很快。"},{"t":"n","text":"「别学我。留三分给自己。」"},{"t":"n","text":"你看着这句话，看了很久。"},{"t":"n","text":"你把手机扣在桌上。办公室里已经没人了，空调还在响。"},{"t":"n","text":"你打开抽屉，那支笔还在里面。"},{"t":"n","text":"笔帽上的划痕朝上。"},{"t":"n","text":"然后你回了一个「好」。"},{"t":"n","text":"你关掉电脑，关灯，锁门。"},{"t":"n","text":"走到楼下，你抬头看了一眼自己办公室的那扇窗。"},{"t":"n","text":"黑着。"}],"quality":{"high":["有一年你去他的城市出差，绕路去看了那间小学的图书室。","窗户很大，光很好。孩子们坐在地上看书，鞋脱在一边。","登记簿放在门口的木桌上。你翻开，最后一页是捐赠人名单。","第一个名字是他。","你在下面写了一行：「来过。」","没有署名。他大概知道是谁。","你走出图书室，天快黑了。","门口有一棵很高的树，叶子落了一地。","你拍了张照片，发给他。","他回：「那棵树是我种的。」"],"mid":["你们的联系一年比一年少。","从每年生日，到隔年生日，到有一次你翻通讯录，看见他的名字，想了一会儿才想起上次说话是哪年。","你点进去，对话框里最后一条是三年前的「新年快乐」。","你退出来，没有发。"],"low":["你有时候会想，如果那天在天台上，你把话说出口了，会怎么样。","你想不出来。","你只知道，后来你遇到的很多人，都会在某个瞬间让你想起他。","比如有人说话很慢，比如有人递东西的时候手停在半空，比如有人在雨天不跑。"]},"id":"baiyu_19","ending":"friend","endingName":"结局三 · 你做得很好（师徒 / 知己）"}]}],"events":[{"id":"by1","title":"咖啡（任意周）","triggerWeek":0,"bg":"office_day","cast":["baiyu"],"intro":[{"t":"n","text":"下午三点，白屿在茶水间找杯子。柜子里一排杯子，没有一个是他的。"},{"t":"n","text":"他每周只来两次，所以从来不放东西。"}],"opts":[{"label":"A","text":"给他带一杯","hint":"顺手带一杯 · 他会记得","eff":{"aff":4.0,"happy":1.0},"reply":[{"t":"n","text":"你从楼下买了两杯，一杯放在他桌上。他看了杯子一眼，说：「你怎么知道我不加糖。」你说不知道，就按自己的口味买的。他把盖子揭开，喝了一口，说：「也行。」"}]},{"label":"B","text":"只买自己的","hint":"不多事 · 安全","eff":{},"reply":[{"t":"n","text":"你拿着自己的杯子回工位。经过会议室，他从里面出来，手里还拿着那个空纸杯。你们点头，错身而过。"}]},{"label":"C","text":"问他喝什么","hint":"先问一句 · 关系近","eff":{"aff":3.0,"eq":1.0},"reply":[{"t":"n","text":"你问他喝什么。他愣了一下，说：「美式。不加糖。」第二天你带了一杯。他接过去，说：「我说过吗。」你说说过。他低头看了看杯子，说：「记性不错。」"}]}]},{"id":"by2","title":"会议记录（任意周）","triggerWeek":0,"bg":"office_day","cast":["baiyu"],"intro":[{"t":"n","text":"客户方的会议拖了两个小时。有人跑题，有人说重复的话。"},{"t":"n","text":"白屿坐在角落，一句话没说，只在纸上写。"}],"opts":[{"label":"A","text":"替他挡一次","hint":"挡一句 · 压力 ↑","eff":{"aff":2.0,"stress":3.0,"eq":1.0},"reply":[{"t":"n","text":"客户方问他一个跟项目无关的问题，你抢在前面接了过去。散会后他说：「下次不用。」你说：「我看你不想答。」他说：「不想答，和不该你答，是两件事。」"}]},{"label":"B","text":"认真记录","hint":"把话记清楚 · 有用","eff":{"aff":4.0,"int":1.0},"reply":[{"t":"n","text":"你把每个人说的话都记了下来，散会后整理成一页纸发给他。他看完，回了两个字：「清楚。」第二天开会，他引用你那一页纸上的原话，把跑题的人拉了回来。"}]},{"label":"C","text":"走神","hint":"听听就好 · 无变化","eff":{"aff":-1.0},"reply":[{"t":"n","text":"你在本子上画了一下午的方框。散会时他经过你身后，看了一眼你的本子，什么也没说。你把本子合上，耳朵有点热。"}]}]},{"id":"by3","title":"体检（第 50 周后）","triggerWeek":50,"bg":"office_day","cast":["baiyu"],"intro":[{"t":"n","text":"体检报告发下来，你顺手把复查预约的短信转发给了他。你也不知道为什么要转发。"}],"opts":[{"label":"A","text":"提醒他去","hint":"提一句 · 有用","eff":{"aff":4.0,"happy":1.0},"reply":[{"t":"n","text":"你说：「你那个去年的单子，还没拆。」他正在签字，笔尖停住。过了一会儿，他说：「下周。」你说：「你上周也说下周。」他抬起头看你，然后笑了一下：「行。你厉害。」"}]},{"label":"B","text":"陪他去","hint":"陪一趟 · 越过一步","eff":{"aff":5.0,"fin":-2.0},"reply":[{"t":"n","text":"周六上午，你们在医院碰面。他穿便装，你差点没认出来。抽完血，他坐在走廊的椅子上，说：「很多年没人陪我来医院了。」他说得很轻，像自言自语。"}]},{"label":"C","text":"不提","hint":"不越界 · 无变化","eff":{},"reply":[{"t":"n","text":"你把手机收起来。这是他的身体，他的时间。你没有资格催。你们照常开会，照常改方案，那张单子还在他包里。"}]}]},{"id":"by4","title":"旧照片（第 55 周后）","triggerWeek":55,"bg":"office_day","cast":["baiyu"],"intro":[{"t":"n","text":"他的笔记本掉在地上，摊开了。里面夹着一张照片。"},{"t":"n","text":"照片上是工地的合影，他站在中间，比现在年轻。"}],"opts":[{"label":"A","text":"问他这是谁","hint":"问一句 · 会听到答案","eff":{"aff":2.0,"happy":-1.0},"reply":[{"t":"n","text":"他蹲下来把照片捡起来，说：「以前的同事。」他把照片夹回去，动作很快。你没有再问。他合上本子，说：「那年我什么都没做成，但人都在。」"}]},{"label":"B","text":"不问","hint":"不问 · 留给他","eff":{"aff":3.0},"reply":[{"t":"n","text":"你把本子捡起来，递给他。他说谢谢。你看见他的手在封面上按了一下，像在确认照片还在。"}]},{"label":"C","text":"说「你以前挺好看」","hint":"玩笑一句 · 气氛松","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你说：「你以前挺好看。」他看了看照片，又看了看你：「以前？」你说：「现在也还行。」他把照片收起来，说：「你这张嘴，在会上怎么那么笨。」"}]}]},{"id":"by5","title":"出差送站（第 56 周后）","triggerWeek":56,"bg":"station_dusk","cast":["baiyu"],"intro":[{"t":"n","text":"他去南边看场地，三天的行程。你知道车次，是自己去查的。"}],"opts":[{"label":"A","text":"去送他","hint":"去一趟 · 关系近","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你在候车厅找到他。他一个人坐着，箱子放在脚边。看见你，他站起来：「你怎么来了。」你说顺路。他说：「你不顺路。」然后他笑了一下：「谢谢。」"}]},{"label":"B","text":"发消息","hint":"发一句 · 稳妥","eff":{"aff":2.0},"reply":[{"t":"n","text":"你发：「路上小心。」他回：「好。」过了一会儿，他又发来一条：「到了告诉你。」你盯着那四个字看了很久。他确实发了，在三个小时以后。"}]},{"label":"C","text":"不去","hint":"不去 · 各自安静","eff":{"aff":-2.0},"reply":[{"t":"n","text":"你没有去。晚上你刷到一条朋友圈，是他在候车厅拍的一杯水。没有任何文字。你点了个赞，又取消了。"}]}]},{"id":"by6","title":"雨天（第 48 周后）","triggerWeek":48,"bg":"office_night_desk","cast":["baiyu"],"intro":[{"t":"n","text":"下班的时候下起了大雨。门口站了一排人，都在等雨小。"},{"t":"n","text":"白屿站在最外面，手里有一把黑色的长柄伞。"}],"opts":[{"label":"A","text":"问他能不能一起走","hint":"问一句 · 会靠近","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你说：「顺路吗。」他看了看伞，又看了看你，说：「伞不大。」你说没事。他把伞撑开，往你那边偏了半寸。走到地铁口，你的肩膀是干的，他右边的袖子湿了一片。"}]},{"label":"B","text":"自己冲进雨里","hint":"不等 · 干脆","eff":{"happy":1.0,"stress":1.0},"reply":[{"t":"n","text":"你把包顶在头上跑过马路。跑到对面，你回头看，他还站在门口，撑着伞，看着你这边。"}]},{"label":"C","text":"等雨停","hint":"等一等 · 无变化","eff":{"aff":1.0},"reply":[{"t":"n","text":"你们都站着。雨下了二十分钟。他先走了，把伞撑开，走进雨里，没有回头。"}]}]},{"id":"by7","title":"生日（第 54 周后）","triggerWeek":54,"bg":"campus_night","cast":["baiyu"],"intro":[{"t":"n","text":"你从项目档案里看到他的身份证复印件。八月十九日。"},{"t":"n","text":"那天他照常来开会，照常改方案，什么也没说。"}],"opts":[{"label":"A","text":"给他买一小块蛋糕","hint":"小一点 · 不隆重","eff":{"aff":5.0,"happy":2.0,"fin":-1.0},"reply":[{"t":"n","text":"你在便利店买了一块切件蛋糕，装在纸盒里。散会后你放在他桌上：「今天你生日。」他看着那个盒子，很久没动。然后他说：「很多年没人记得了。」他说完，把盒子打开，用塑料叉子吃了一口。"}]},{"label":"B","text":"发一条消息","hint":"一句话 · 得体","eff":{"aff":3.0},"reply":[{"t":"n","text":"你发：「生日快乐。」他回：「谢谢。」过了一会儿，他补了一句：「你怎么知道。」你说档案里看到的。他回了一个「哦」。就再没有别的了。"}]},{"label":"C","text":"不提","hint":"不提 · 无变化","eff":{},"reply":[{"t":"n","text":"你什么也没说。他走的时候，你看见他一个人在大厅里站了一会儿，然后推门出去。外面在下雨。"}]}]},{"id":"by8","title":"电梯（第 47 周后）","triggerWeek":47,"bg":"office_night_desk","cast":["baiyu"],"intro":[{"t":"n","text":"十一点，你们一起下楼。电梯到七楼的时候晃了一下，停住了。"},{"t":"n","text":"灯灭了一半，只剩应急灯。对讲机里有电流声。"},{"t":"n","text":"他按下对讲机，报了楼层和人数。然后他退回来，站到离你最远的那个角落。"},{"t":"n","text":"电梯里很静。你能听见自己的呼吸。"}],"opts":[{"label":"A","text":"问他怕不怕","hint":"闲聊一句 · 关系近","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你问他怕不怕。他说：「不怕。」过了一会儿，他补了一句：「但这个月第二次了。物业该修了。」你笑出来。他也笑了一下，说：「笑什么。」你说：「你连被困在电梯里都在想流程。」"}]},{"label":"B","text":"靠着电梯壁不说话","hint":"不说话 · 等它好","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"你们谁也不说话。十五分钟后，电梯动了。门开的时候，他先出去，站在门边等你。走到大厅，他说：「明天跟行政提一下，那个电梯要检修。」"}]},{"label":"C","text":"说「你站那么远干嘛」","hint":"点破一句 · 有点尴尬","eff":{"aff":3.0,"eq":1.0},"reply":[{"t":"n","text":"你说：「你站那么远干嘛。」他愣了一下，说：「空间小。」你说：「空间再小也够站两个人。」他没有动，只是把手插进口袋。电梯动起来的时候，他看了你一眼。"}]}]}],"endingNames":{"stay":"结局一 · 这次，他没留三分","miss":"结局二 · 有些人教你长大（爱过 / 错过）","friend":"结局三 · 你做得很好（师徒 / 知己）"}};
